(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-lcm-fewstep"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-1\">一 · 事故现场：当 30 步的账单压垮一个文生图服务</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-2\">二 · 它改的是采样轨迹，不是数值格式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-3\">三 · 代价核算：省下来的是什么，花出去的是什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-4\">四 · 适用边界：哪些业务分层该用它，哪些不该</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-5\">五 · 一个可执行的判断：先分层，再叠 kernel</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-6\">六 · 少步采样救不了的那一类请求：失效边界与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-7\">七 · 请求进入：从 prompt 到条件嵌入与初始 latent</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-8\">八 · 跳步时间表：离散时间点的选择与 scheduler 更新</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-9\">九 · 学生前向：单次 DiT 替代双 batch 的账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-10\">十 · 一致性自洽项在推理期的残留影响</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-11\">十一 · 末端 latent 到像素：VAE 解码的固定尾巴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-12\">十二 · 按 KV/批流动看整条链的代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-13\">十三 · 跳步采样的边界：失效条件与系统代价拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-14\">十四 · 少步采样的失效边界与端到端账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-15\">十五 · 一致性映射的逐项解剖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-16\">十六 · CFG 并入条件嵌入的推导路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-17\">十七 · 端到端时延公式与跳步的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-18\">十八 · 可实现的蒸馏伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-19\">十九 · 退化模式与分层步数的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-20\">二十 · 与量化、注意力的叠加次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-21\">二十一 · 失效边界与端到端代价账：一致性蒸馏不是免费午餐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-22\">二十二 · 请求形态：什么流量吃得下少步采样</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-23\">二十三 · 长度分布：latent 分辨率与批内碎片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-24\">二十四 · 并发与批大小：CFG 蒸馏后的批几何</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-25\">二十五 · 负载不对时的三种崩法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-26\">二十六 · 配方落地：分层路由与桶化调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-27\">二十七 · 负载错配时的三重失效与配方边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-28\">二十八 · 硬件档位：按步数预算反推算力与显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-29\">二十九 · 并行拓扑：DiT 张量并行与 VAE 分块的解耦</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-30\">三十 · 量化方案：与少步采样的叠加次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-31\">三十一 · KV 策略：少步场景下 KV 的真实角色</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-32\">三十二 · 调度参数：分层步数与 SLO 的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-33\">三十三 · 可复现配置思路：从约束到参数的推导链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-34\">三十四 · 少步配方的边界：何时该退回多步、何时必须重训</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-35\">三十五 · 少步之后，瓶颈从 DiT 前向挪到别处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-36\">三十六 · 显存：激活峰值降了，KV 式缓存没有，但驻留请求数才是关键</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-37\">三十七 · 带宽与通信：少步放大的是权重搬运占比，不是单步算术强度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-38\">三十八 · 功耗与能效：空转与固定开销决定单位图成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-39\">三十九 · 尾延迟：串行链短了，但排队与固定开销成了新尾巴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-40\">四十 · 规模上去以后，先崩的是调度与冷启动，不是 kernel</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-41\">四十一 · 少步之后，瓶颈从 DiT 前向挪到了别处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-42\">四十二 · 精度退化：少步映射的误差放大与分层诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-43\">四十三 · OOM 与显存抖动：CFG 蒸馏后的隐性峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-44\">四十四 · 批抖动与路由不均：步数通道的负载守恒</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-45\">四十五 · 尾延迟尖刺：VAE 与调度器的耦合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-46\">四十六 · 监控与回滚：把诊断信号做成可执行开关</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-47\">四十七 · 少步采样的失效边界：从画质退化到路由塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-48\">四十八 · 对照轴：改采样轨迹，还是改数值与 kernel</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-49\">四十九 · 决策表：五类相邻手段的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-50\">五十 · 与整流流直线采样器的分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-51\">五十一 · 与阶段级扩散服务流水、分离式部署的关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-52\">五十二 · 分层步数与业务分档的决策规则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-53\">五十三 · 叠加顺序与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-lcm-fewstep-sec-54\">五十四 · 同族取舍：步数压缩的边界与代价核算</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:517px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 516.6 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"434.6\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">教师模型在 latent 上跑 PF-ODE 生成 (x_t, x_0) …</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"434.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">学生网络以 x_t 与 t 为输入直接预测 x_0，损失为与教师 x_0 …</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"434.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">蒸馏时把 CFG 引导尺度并入条件嵌入，学生单次前向替代双 batch</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"434.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">推理按 4–8 个离散时间点跳步，每步一次 DiT 前向加一次 sched…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"434.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">末端 latent 送 VAE 解码，跳过冗余的高噪步</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-lcm-fewstep-sec-1\">一 · 事故现场：当 30 步的账单压垮一个文生图服务</h3>\n<p>先看一个不需要虚构数字的失败链条。某文生图服务在 Blackwell 单卡上跑标准 latent 扩散：每个请求要 20–50 次 DiT 前向，每次前向还要因为 CFG 走两遍 batch——条件分支与无条件分支各一次。端到端时延按 <span class=\"formula\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$$</span> 线性放大，其中 <span class=\"formula\">$$t_{\\text{DiT}}$$</span> 在 CFG 双 batch 下近似翻倍。工程上的后果不是“慢一点”，而是三件事同时发生：单请求延迟越过交互式 SLO；为压延迟而放大并发，KV 之外的激活与中间 latent 占用把显存推到上限，连续批处理被迫缩小批大小；批大小一缩，GPU 利用率掉下去，单位请求成本反而上升。这是一个典型的负反馈：越想用批处理摊薄成本，越被单请求步数锁死。</p>\n<p>更具体的失效形态出现在长 prompt 场景。运营侧为了“不出错”把默认步数钉在 30 步以上，CFG 尺度也调得偏高，于是每个请求的算力预算被固定死；当流量峰值到来，调度器只能按请求数排队，队列延迟以分钟计。此时即使 NVFP4 量化、FA3 注意力这些 kernel 级优化已经把单次前向压到很低，端到端仍然被 <span class=\"formula\">$$N_{\\text{step}}$$</span> 这个乘数按住。这就是本算法要解决的具体推理问题：<strong>步数是一阶项，不是二阶项</strong>。把 20–50 步压到 4–8 步，端到端时延降 4–8 倍，而且不需要改推理框架——这是它区别于数值格式与注意力 kernel 优化的根本位置。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-2\">二 · 它改的是采样轨迹，不是数值格式</h3>\n<p>潜空间一致性少步采样的机制按数据流顺序可以拆成三段。第一段是教师轨迹生成：教师模型在 latent 空间跑 PF-ODE，从噪声出发沿轨迹采样，记录任意时刻的 <span class=\"formula\">$$(x_t,x_0)$$</span> 配对，其中 <span class=\"formula\">$$x_0$$</span> 是该轨迹的终点。第二段是学生映射：学生网络以 <span class=\"formula\">$$x_t$$</span> 与 <span class=\"formula\">$$t$$</span> 为输入，直接预测 <span class=\"formula\">$$x_0$$</span>，核心假设是一致性映射 <span class=\"formula\">$$f_\\theta(x_t,t)\\approx x_0$$</span>，损失为与教师终点的距离加上自洽项：</p>\n<div class=\"formula\">$$\\mathcal{L}=\\mathbb{E}\\left[\\|f_\\theta(x_t,t)-x_0\\|^2\\right]+\\lambda\\,\\mathcal{L}_{\\mathrm{cons}},\\quad \\mathcal{L}_{\\text{cons}}=\\mathbb{E}_{t}\\big\\|f_{\\theta}(x_{t},t)-f_{\\theta}(x_{t'},t')\\big\\|^{2}$$</div>\n<p>自洽项约束的是同一条轨迹上不同时刻的预测彼此一致，避免学生只在离散锚点上拟合、锚点之间塌陷。第三段是 CFG 蒸馏：把引导尺度并入条件嵌入，学生单次前向就替代了原来的条件/无条件双 batch。推理时按 4–8 个离散时间点跳步，每步一次 DiT 前向加一次 scheduler 更新，末端 latent 送 VAE 解码，跳过冗余的高噪步。</p>\n<p>这里必须把边界说清楚：它改的是<strong>采样步数与 CFG 结构</strong>，不是数值格式，也不是注意力 kernel。因此它与 NVFP4 混合精度量化、FP8 注意力与 GEMM、异步 FA3 注意力是正交叠加关系——那些条目压的是 <span class=\"formula\">$$t_{\\text{DiT}}$$</span>，本算法压的是 <span class=\"formula\">$$N_{\\text{step}}$$</span> 和 CFG 的 batch 因子。工程判断上，两者叠加才有意义：只做量化不做少步，乘数仍在；只做少步不做量化，单次前向仍贵。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-3\">三 · 代价核算：省下来的是什么，花出去的是什么</h3>\n<p>收益端有两笔明确的账。第一笔是步数：30 步到 4–8 步，端到端时延降 4–8 倍，这是线性乘数的直接削减，对交互式 SLO 是决定性的。第二笔是 CFG 蒸馏：单次前向替代双 batch，显存与算力同时减半——注意这不是“近似减半”，而是 batch 维度上少了一路条件分支，激活与权重读取都少一份。对服务端而言，这两笔账合起来意味着同样的 GPU 可以承载更多并发，或者在同样并发下把批大小留出余量给连续批处理。</p>\n<p>代价端同样要按推理系统口径算。其一是画质退化具有<strong>文本复杂度相关性</strong>：少步采样对文本复杂组合与细粒度文字生成退化明显，退化不是均匀分布的，而是集中在长 prompt、多对象绑定、文字渲染这类请求上。其二是架构绑定：蒸馏学生绑定教师架构，换底模必须重训，冷启动成本高；直接复用旧学生会导致分布错配与画质崩坏——这不是精度问题，是映射目标变了。其三是引导空间收窄：CFG 蒸馏把引导尺度并入条件嵌入后，引导强度调节空间收窄，极端尺度下易出现过饱和或结构塌陷，运营侧不能再靠“把 CFG 调高一点”兜底。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>标准扩散</th><th>少步一致性</th><th>系统含义</th></tr></thead><tbody><tr><td>DiT 前向次数</td><td>20–50</td><td>4–8</td><td>时延乘数降 4–8 倍</td></tr><tr><td>CFG batch 因子</td><td>2（双 batch）</td><td>1（尺度入条件嵌入）</td><td>显存与算力减半</td></tr><tr><td>画质风险</td><td>低（步数冗余）</td><td>长 prompt 与文字退化</td><td>需按业务分层选步数</td></tr><tr><td>换底模成本</td><td>无</td><td>必须重训学生</td><td>冷启动与版本管理成本</td></tr></tbody></table>\n\n<h3 id=\"alg-lcm-fewstep-sec-4\">四 · 适用边界：哪些业务分层该用它，哪些不该</h3>\n<p>适用边界可以按“画质敏感度 × 文本复杂度”切成四块。低复杂度、低文字要求的批量出图——社交配图、商品场景图、风格化缩略图——是 4–8 步的主场，端到端时延降 4–8 倍直接转化为单位成本下降与队列缩短。高复杂度、细粒度文字要求的请求——海报文字、UI 稿、多对象精确绑定——应保留较高步数或走另一条路径，因为退化随文本复杂度上升，业务画质投诉会集中出现在长 prompt 场景。中间地带则按业务分层选择步数：同一套服务里给不同请求打步数档位，而不是全局钉死一个值。</p>\n<p>规模上限受两条约束。第一条是教师架构绑定：学生是教师轨迹的蒸馏产物，教师换代（换底模、换分辨率体系、换条件编码方式）就必须重训，冷启动成本高，这决定了它不适合底模高频迭代的业务。第二条是引导调节空间：CFG 蒸馏后极端尺度易过饱和或结构塌陷，若业务依赖大幅调 CFG 做风格控制，少步学生会把这条控制通道收窄。工程上应把这两条写成准入条件，而不是上线后再补。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-5\">五 · 一个可执行的判断：先分层，再叠 kernel</h3>\n<p>把上面的边界落到部署决策上，顺序应当是：先按业务分层确定每个请求的步数档位与是否允许 CFG 蒸馏，再决定是否叠加 NVFP4 量化与 FA3 注意力。理由是乘数优先级——<span class=\"formula\">$$N_{\\text{step}}$$</span> 与 CFG batch 因子是端到端时延的一阶项，kernel 优化是二阶项；先压一阶项，二阶项的收益才会体现在 SLO 上而不是被步数吃掉。反过来，若先做量化再考虑少步，很可能因为量化后的画质余量被误判为“不能再降步数”，从而错过真正的成本拐点。</p>\n<p>另一个具体机制是跳步点的选择：推理按 4–8 个离散时间点跳步，跳过的是冗余的高噪步。高噪段对最终画质的贡献主要在大结构而非细节，因此跳步对结构类请求相对安全，对文字与细粒度纹理则风险集中。工程上可以把跳步点与业务分层绑定：文字类请求保留更多低噪步，结构类请求压缩高噪步。这一步不需要改推理框架，只需要在 scheduler 的时间表上做配置，这也是它“无需改推理框架”这一优点的实际落点。</p>\n<p>最后落在一条工程判断上：潜空间一致性少步采样不是“更快的扩散”，而是<strong>用画质的分层退化换取时延乘数的削减</strong>。它的正确用法是把它当作服务分层的一个维度——步数档位、CFG 蒸馏开关、教师版本绑定——而不是一个全局默认值。凡是把 4 步钉死给所有请求的服务，画质投诉必然集中在长 prompt；凡是换底模不重训学生的服务，分布错配会以画质崩坏的形式暴露。这两条不是风险提示，是准入条件。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-6\">六 · 少步采样救不了的那一类请求：失效边界与系统代价</h3>\n<p>把这条链路放到线上，最先暴露问题的不是平均时延，而是长 prompt 场景的画质投诉集中爆发。某文生图服务在高峰期把采样步数从 30 压到 6，端到端时延按 $T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$ 线性收缩，GPU 利用率与单位成本同步改善；但监控里投诉工单的分布发生了结构性偏移——短 prompt、单一主体的请求几乎无感，而包含多主体空间关系、指定文字排版、材质与光照叠加描述的长 prompt 出现明显的组合错位与文字糊化。原因不在调度层，而在一致性映射本身：学生网络 $f_\\theta(x_t,t)\\approx x_0$ 是在教师 PF-ODE 轨迹上做点对点回归，$\\mathcal{L}=\\mathbb{E}[\\|f_\\theta(x_t,t)-x_0\\|^2]+\\lambda\\mathcal{L}_{\\text{cons}}$ 里的期望 $\\mathbb{E}_t$ 对时间步做了平均，高噪步被跳过后，那些依赖多步渐进修正才能收敛的细粒度约束失去了被反复修正的机会。少步采样不是把 30 步“压缩”成 6 步的等价变换，而是把一条需要迭代逼近的轨迹替换成一次大跨度的直接预测，跨度越大，条件信息中未被教师轨迹充分展开的部分就越容易丢失。</p>\n<p>这决定了它的适用边界必须按业务分层来划，而不是全局一刀切。可用的工程判据是把请求按“文本复杂度 × 是否含文字渲染 × 是否含多主体约束”分成若干档，高档位保留 20–50 步的标准采样路径，低档位走 4–8 步的一致性学生；分层键应放在请求入口的预处理阶段，而不是等到生成后靠人工审核回捞。代价是显存侧要同时驻留两套权重——教师或标准模型与蒸馏学生，KV/激活峰值按较大者计，CFG 蒸馏后学生单次前向替代双 batch 确实让显存与算力同时减半，但双模型共存又把这部分收益部分吃掉，实际收益取决于两套权重的驻留比例与换入换出策略。吞吐上，4–8 步带来的 4–8 倍时延下降在混合负载下会被高档位请求稀释，容量规划必须按分层后的加权步数而非最低步数估算，否则 SLO 会在长 prompt 占比上升时突然击穿。</p>\n<p>第二个失效条件更硬：蒸馏学生绑定教师架构。学生是在特定教师的 latent 空间、特定 scheduler、特定条件嵌入结构下训出来的，换底模不是换一个 checkpoint 那么简单，而是换了一整套 $x_t$ 的分布与 PF-ODE 轨迹形状，直接复用旧学生会导致分布错配，画质不是缓慢退化而是崩坏式塌陷。冷启动成本因此成为规模上限的真正约束：每换一次底模就要重跑教师轨迹生成、配对数据构造与一致性蒸馏，这段时间内新底模只能走标准多步路径，等于把刚省下来的单位成本又还回去。工程上的应对是把学生版本与底模版本做强绑定并在路由层显式标注，禁止跨版本静默复用；同时对蒸馏产物的验收不能只看 FID 类整体指标，必须补一组长 prompt 与文字渲染的定向评测集，否则整体指标会被简单请求拉平而掩盖长尾退化。</p>\n<p>第三个代价来自 CFG 蒸馏本身。把引导尺度并入条件嵌入后，学生单次前向替代双 batch，省掉的是整整一半的算力与显存带宽，但引导强度的可调空间随之收窄：推理时不再有独立的 $w$ 可以在线扫描，极端尺度下容易出现过度饱和或结构塌陷，而这恰恰是运营侧做风格调节最常用的旋钮。若业务需要保留宽引导范围，就得为不同尺度分别蒸馏或多个条件嵌入分支，冷启动成本按分支数翻倍。这也划出了它与相邻优化的叠加关系：它改的是采样步数与 CFG 结构，不动数值格式与注意力 kernel，因此可以与 NVFP4 量化、FA3 注意力叠加，但叠加时要注意量化误差在少步大跨度预测下被放大——每步的预测跨度更大，低精度带来的偏差缺少后续步的修正机会，量化校准集必须覆盖长 prompt 分层，否则省下的算力会被返工成本抵消。</p>\n<table class=\"mini\"><thead><tr><th>边界维度</th><th>可接受</th><th>失效表现</th><th>系统代价</th></tr></thead><tbody><tr><td>文本复杂度</td><td>短 prompt、单一主体</td><td>多主体空间关系错位</td><td>需双模型共存，显存按较大者计</td></tr><tr><td>文字渲染</td><td>无文字或大字号</td><td>细粒度文字糊化</td><td>高档位回退多步，吞吐被稀释</td></tr><tr><td>底模变更</td><td>底模冻结期内</td><td>跨版本复用导致画质崩坏</td><td>重训冷启动，期间退回标准路径</td></tr><tr><td>引导尺度</td><td>窄范围固定风格</td><td>极端尺度过饱和/塌陷</td><td>多分支蒸馏，成本按分支翻倍</td></tr></tbody></table>\n<h3 id=\"alg-lcm-fewstep-sec-7\">七 · 请求进入：从 prompt 到条件嵌入与初始 latent</h3>\n<p>一个少步采样请求在服务端的第一个动作不是 DiT 前向，而是把文本条件压成学生网络能吃的嵌入。标准扩散里 CFG 需要正负两份条件、每步跑两次前向；一致性蒸馏把引导尺度 $w$ 在训练期就折进条件嵌入，推理期只剩一条条件通路。工程上的输入是 tokenized prompt 加一个标量 $w$，输出是形状为 $[B, L, d_{\\text{cond}}]$ 的条件张量，以及从高斯噪声采样的初始 latent $x_{T}$。这一步的代价不在算力而在显存与带宽：条件张量本身很小，但文本编码器（通常是冻结的 T5 或 CLIP 类）要占一份常驻权重，且首 token 延迟里含一次编码器前向。对短 prompt 这是毫秒级固定开销，对长 prompt 则随 $L$ 线性增长。具体例子：批内 8 条请求、每条 77 token、$d_{\\text{cond}}=4096$，条件张量约 2.5 MB（BF16），相对 KV 与激活可忽略，但编码器权重的常驻占用决定了单卡能放几个模型实例。这里的关键判断是：条件编码应做请求级批合并，而不是逐条串行，否则在 4–8 步的极短采样窗口里，编码器延迟占比会被放大。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-8\">八 · 跳步时间表：离散时间点的选择与 scheduler 更新</h3>\n<p>少步采样的核心是把连续 PF-ODE 轨迹离散成 4–8 个时间点 $\\{t_1,\\dots,t_N\\}$，$N\\in[4,8]$。输入是上一步的 latent $x_{t_i}$ 与当前时间嵌入 $t_i$，输出是学生预测的 $\\hat{x}_0=f_\\theta(x_{t_i},t_i)$，随后 scheduler 用 $\\hat{x}_0$ 与 $x_{t_i}$ 反解出 $x_{t_{i+1}}$。每步的算力代价就是一次完整 DiT 前向；调度代价是一次逐元素的 scheduler 更新，访存量与 latent 同阶。端到端时延按 $T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$ 线性缩放，因此 $N$ 从 30 降到 6 就是把 DiT 部分压到五分之一。时间表不是均匀的：高噪段跳得狠、低噪段留得密，因为 $f_\\theta$ 在高噪处预测 $x_0$ 的方差大，误差会被后续步放大。伪代码思路是：对每个 $i$，先算 $\\hat{x}_0$，再用 $\\hat{x}_0$ 与 $x_{t_i}$ 的线性组合得到 $x_{t_{i+1}}$，最后一步直接取 $\\hat{x}_0$ 作为末端 latent。工程代价体现在批调度上——$N$ 越小，单请求占用 SM 的时间越短，连续批处理的填充率越难维持，GPU 利用率反而可能因请求太短而下降，需要靠更大批或更激进的请求聚合来补。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-9\">九 · 学生前向：单次 DiT 替代双 batch 的账</h3>\n<p>每个离散时间点上，学生网络接收 $x_{t_i}$、$t_i$ 与条件嵌入，输出 $\\hat{x}_0$。这一步是整条链路的重心：输入激活 $[B, C, H, W]$ 的 latent，输出同形状的 $x_0$ 预测，中间经过 DiT 的注意力与 GEMM 堆叠。CFG 蒸馏的收益在这里兑现——标准做法每步要跑正负两份条件、批维翻倍，显存与算力都乘 2；蒸馏后引导尺度并入嵌入，单次前向即完成。显存账：激活、KV（若 DiT 用注意力缓存）、权重三部分，批维减半直接砍掉激活与注意力的那部分。算力账：每步 MMA 次数减半，$N$ 步总 GEMM 量按 $N\\times B$ 缩放。具体例子：批 8、latent $64\\times64\\times4$、$N=6$，若不蒸馏则等效批 16、12 次前向；蒸馏后 6 次前向、批 8，GEMM 总量约为前者的四分之一。这一步与数值格式正交：NVFP4/FP8 量化改的是每次前向内部的精度与带宽，少步改的是前向次数，两者可叠加，但量化误差在少步下缺少后续步的纠偏机会，需要更保守的校准。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-10\">十 · 一致性自洽项在推理期的残留影响</h3>\n<p>训练损失 $\\mathcal{L}=\\mathbb{E}\\big[\\|f_\\theta(x_t,t)-x_0\\|^2\\big]+\\lambda\\,\\mathcal{L}_{\\text{cons}}$ 里，第二项约束不同时间点的预测互相自洽：$\\mathcal{L}_{\\text{cons}}=\\mathbb{E}_{t}\\big\\|f_{\\theta}(x_{t},t)-f_{\\theta}(x_{t'},t')\\big\\|^{2}$。推理期看不到这一项，但它决定了跳步的可行性——自洽项权重 $\\lambda$ 越大，学生在稀疏时间点上的预测越接近，跳步误差越小；$\\lambda$ 过小则各时间点预测发散，4 步采样会出现结构漂移。工程含义是：时间表不能脱离训练配方单独调，换时间点集合等于换了一个未被训练覆盖的输入分布。代价体现在画质而非时延：自洽性不足时，末端 latent 的细节熵偏高，VAE 解码后表现为纹理噪点或语义错位。具体例子：文本复杂组合（多物体、空间关系、细粒度文字）在 4 步下退化最明显，因为这类 prompt 的 $x_0$ 分布本身方差大，稀疏时间点的自洽约束覆盖不到。分层策略由此而来：简单 prompt 走 4 步，复杂 prompt 回退到 6–8 步，用步数换画质，代价是这批请求的 $T_{\\text{e2e}}$ 上升。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-11\">十一 · 末端 latent 到像素：VAE 解码的固定尾巴</h3>\n<p>最后一步输出 $\\hat{x}_0$ 后，链路把 latent 送进 VAE 解码器。输入是 $[B, C, H, W]$ 的 latent，输出是 $[B, 3, kH, kW]$ 的像素图，$k$ 为 VAE 上采样倍率。这一步的时延 $t_{\\text{VAE}}$ 不随 $N$ 缩放，因此在少步 regime 下它成了端到端时延里不可压缩的固定项：$N$ 越小，VAE 占比越高。显存代价来自解码激活，像素分辨率越高越显著，分块解码是常规手段（该主题另有专述，此处只指路）。带宽代价是 latent 读出加像素写回，对高分辨率请求是主要访存项。具体例子：$N=6$ 时 DiT 部分被压到很小，若 VAE 解码仍按整图一次性做，单请求时延里 VAE 可能占到可观比例，批内多请求并发时显存峰值由解码激活主导而非 DiT 激活。工程判断是：少步采样必须与 VAE 解码的批调度一起设计，否则步数收益会被固定尾巴吃掉；把解码与下一步请求的 DiT 前向重叠，是维持 GPU 利用率的关键。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-12\">十二 · 按 KV/批流动看整条链的代价结构</h3>\n<p>把上述步骤按批与 KV 流动串起来：条件编码（请求级，固定开销）→ 初始 latent 采样（逐请求，访存小）→ $N$ 次 DiT 前向（批级，算力与激活主导）→ scheduler 更新（逐元素，带宽小）→ VAE 解码（批级，显存与带宽主导）。整条链的瓶颈随 $N$ 移动：$N$ 大时 DiT 算力是瓶颈，$N$ 小时 VAE 与批填充率成为瓶颈。少步把 DiT 的 KV 与激活压力按 $N$ 缩减，但批内请求变短后，连续批处理的调度窗口变窄，KV 复用率下降。表格对比各步的代价归属：</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入→输出</th><th>主导代价</th><th>随 $N$ 缩放</th></tr></thead><tbody><tr><td>条件编码</td><td>prompt→条件张量</td><td>编码器权重常驻、首 token 延迟</td><td>否</td></tr><tr><td>初始 latent</td><td>噪声→$x_T$</td><td>访存</td><td>否</td></tr><tr><td>DiT 前向 ×N</td><td>$x_{t_i}$→$\\hat{x}_0$</td><td>GEMM 算力、激活显存</td><td>是，线性</td></tr><tr><td>scheduler 更新</td><td>$\\hat{x}_0,x_{t_i}$→$x_{t_{i+1}}$</td><td>逐元素带宽</td><td>是，线性</td></tr><tr><td>VAE 解码</td><td>$\\hat{x}_0$→像素</td><td>解码激活显存、像素写回带宽</td><td>否</td></tr></tbody></table>\n<p>工程判断落在批调度上：少步采样的单请求 DiT 时间被压短，若批大小不随之放大，SM 占用率会掉；而放大批又推高激活显存，与 VAE 解码峰值叠加。可行做法是把 $N$ 作为分层旋钮——简单请求 4 步、大批聚合，复杂请求 6–8 步、小批保画质——让批内请求的步数尽量一致，避免长短请求混批导致的尾部等待。这一步的机制性结论是：少步的收益不是无条件 4–8 倍，只有在 VAE 与批填充率同步优化后，$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$ 里的两项才同时受控。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-13\">十三 · 跳步采样的边界：失效条件与系统代价拆解</h3>\n<p>按请求流动顺序看，这条链路在推理侧被压成四段：请求进入后先做 prompt 编码与条件嵌入，其中已并入 CFG 引导尺度；随后按 4–8 个离散时间点跳步，每步一次 DiT 前向加一次 scheduler 更新；末端 latent 直接送 VAE 解码，跳过全部冗余高噪步。每步的输入是当前 latent 与离散时刻 <em>t</em>，输出是学生网络直接预测的 <em>x</em><sub>0</sub> 估计，代价是一次完整 DiT 前向的算力与激活显存；scheduler 更新只做代数运算，代价可忽略但不可省，因为跳步间隔越大，单步更新误差被放大的倍数越高。整条链路的端到端时延仍服从 <div class=\"formula\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$$</div> 当 <em>N</em><sub>step</sub> 从 20–50 压到 4–8，DiT 项缩到原来的四分之一到八分之一，VAE 解码项不随步数缩放，于是它在总时延中的占比被动抬升——这是跳步方案第一个结构性代价：继续压步数的边际收益递减，而 VAE 成为新的时延地板。</p>\n<p>失效条件集中在语义侧而非数值侧。少步采样对文本复杂组合与细粒度文字生成退化明显，根因是学生网络在极少离散点上必须一次性完成从高噪到 <em>x</em><sub>0</sub> 的大跨度映射，条件嵌入里被压缩的 CFG 引导信息无法在单步内充分展开，长 prompt 中的多实体绑定与字形结构首先崩坏。工程判断是必须按业务分层选择步数：对构图与风格类请求走 4–6 步，对含文字渲染、多对象空间关系的请求保留 8 步甚至回退到标准多步路径，否则画质投诉会集中出现在长 prompt 场景。第二个失效条件是架构绑定：蒸馏学生绑定教师架构，换底模必须重训，直接复用旧学生会导致分布错配与画质崩坏；冷启动成本落在重训管线与配对轨迹生成上，教师跑 PF-ODE 产出 <em>(x<sub>t</sub>, x<sub>0</sub>)</em> 配对的离线开销随底模更换而重复支付。第三个是引导尺度收窄：CFG 蒸馏把引导尺度并入条件嵌入后，运行时调节空间变小，极端尺度下易出现过饱和或结构塌陷，服务端不能再用调 CFG 作为画质兜底手段。</p>\n<p>系统代价要分项记账。算力与显存侧，CFG 蒸馏后单次前向替代双 batch，显存与算力同时减半，这是少步之外的第二重收益，但它以放弃运行时引导强度扫描为代价。批调度侧，跳步把单请求 DiT 前向次数压到个位数，连续批处理窗口内每请求占用的 GPU 时间片变短，吞吐上升但调度粒度变细，批内请求的步数分层若不一致，会出现同批内长短步请求互相等待的尾部效应，需要按步数档位分桶排队。带宽侧，VAE 解码占比抬升意味着末端 latent 到像素的张量搬运成为不可忽视的一项，尤其在多卡并行拓扑下，解码若与 DiT 不同卡，跨卡搬运会吃掉部分跳步收益。数值格式上它改的是采样步数与 CFG 结构而非数值格式或注意力 kernel，因此可与 NVFP4 量化、FA3 注意力叠加，但量化误差在 4 步极端档位下缺少后续步的误差修正机会，需在分层策略里把低步数档与高精度格式绑定。规模上限受教师架构绑定与重训成本约束，扩张靠的是多底模多学生的并行维护，而不是单学生通吃。</p>\n<table class=\"mini\"><thead><tr><th>链路段</th><th>输入 → 输出</th><th>主要代价</th><th>失效敏感点</th></tr></thead><tbody><tr><td>条件嵌入</td><td>prompt → 含 CFG 尺度的嵌入</td><td>编码算力，可忽略</td><td>引导尺度调节空间收窄</td></tr><tr><td>跳步 DiT</td><td>(x<sub>t</sub>, t) → x<sub>0</sub> 估计</td><td>N<sub>step</sub>·t<sub>DiT</sub>，单次前向</td><td>长 prompt、文字渲染退化</td></tr><tr><td>scheduler</td><td>x<sub>0</sub> 估计 → 下一时刻 latent</td><td>代数运算，误差随间隔放大</td><td>大步长下误差累积</td></tr><tr><td>VAE 解码</td><td>末端 latent → 像素</td><td>t<sub>VAE</sub>，成新时延地板</td><td>跨卡搬运吃掉跳步收益</td></tr></tbody></table>\n\n<h3 id=\"alg-lcm-fewstep-sec-14\">十四 · 少步采样的失效边界与端到端账本</h3>\n<p>一致性蒸馏把采样步数压到 4–8，但这条路径的收益不是无条件的。失效首先出现在文本侧：少步映射把整条 PF-ODE 轨迹折叠成少数几个跳点，条件嵌入里承载的细粒度约束（多物体空间关系、长 prompt 中的属性绑定、画面内文字）在高噪阶段被一次性跳过，学生网络没有足够的中间监督去逐步修正，退化随文本复杂度单调上升。工程上的对策是按业务分层配置步数——短 prompt、风格化、背景类请求走 4 步，含文字排版或复杂组合的请求保留 6–8 步，并把分层判据前置到请求路由层，而不是让同一份学生网络硬扛全部流量。第二个边界是架构绑定：学生权重与教师的时间离散化方式、latent 通道布局、条件嵌入维度强耦合，换底模即等于重训，冷启动成本必须计入容量规划，直接复用旧学生会产生分布错配，表现为结构性崩坏而非轻微画质下降。第三个边界在 CFG 蒸馏本身：引导尺度被并入条件嵌入后，推理期可调的引导强度区间收窄，极端尺度下出现过饱和或结构塌陷，需要在上线前把可用尺度区间测出来并写进服务契约。</p>\n<p>把代价拆到端到端账本上，少步方案的收益与残余开销一目了然：</p>\n<div class=\"formula\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$$</div>\n<p>步数从 20–50 降到 4–8，DiT 前向项被压缩 4–8 倍，但 VAE 解码项不随步数缩放，于是它在总时延中的占比被动抬升——当 DiT 项被压到与 VAE 同量级时，继续减步的边际收益迅速衰减，优化重心应转向解码与 latent 传输。CFG 蒸馏让单次前向替代双 batch，显存与算力同时减半，这是少步之外的第二重收益，但它换来的是引导调节空间收窄，属于用灵活性换吞吐的显式交易。批调度层面，步数减少意味着单请求占用 SM 的时间片变短，连续批处理下批内请求的完成时刻更集中，调度器可以用更小的批窗口维持同等吞吐，代价是批内时间离散度上升、尾部请求的等待抖动更明显。由于该方案只改采样步数与 CFG 结构、不动数值格式与注意力 kernel，它可以与 NVFP4 量化、FA3 注意力直接叠加，量化误差与少步近似误差会共同作用于同一批高噪跳点，因此量化校准集必须覆盖长 prompt 与含文字样本，否则两类误差叠加会在最需要保真的请求上同时爆发。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>输入→输出</th><th>系统代价</th></tr></thead><tbody><tr><td>跳步采样</td><td>latent + t → 单步 DiT 前向</td><td>N_step 次前向，4–8 倍时延压缩</td></tr><tr><td>CFG 蒸馏</td><td>条件嵌入含引导尺度 → 单次前向</td><td>显存与算力减半，尺度区间收窄</td></tr><tr><td>VAE 解码</td><td>末端 latent → 像素</td><td>不随步数缩放，占比被动抬升</td></tr></tbody></table>\n<h3 id=\"alg-lcm-fewstep-sec-15\">十五 · 一致性映射的逐项解剖</h3>\n<p>把核心公式拆成两半看：<span class=\"formula\">$$f_\\theta(x_t,t)\\approx x_0,\\quad \\mathcal{L}=\\mathbb{E}\\left[\\|f_\\theta(x_t,t)-x_0\\|^2\\right]+\\lambda\\,\\mathcal{L}_{\\mathrm{cons}}$$</span>。第一项是<strong>端点回归项</strong>，$x_0$ 不是数据集的真实图像，而是教师 PF-ODE 从同一 $x_t$ 出发积分到终点的落点——这一点决定了它不是普通回归，而是把教师的轨迹终点当作标签。第二项 $\\mathcal{L}_{\\mathrm{cons}}$ 是自洽项，约束学生在相邻时间点上的预测彼此一致，而不是各自独立地拟合教师。$\\lambda$ 是两者的权衡：$\\lambda$ 偏大时学生更平滑、跨步跳得更稳，但对教师终点的贴合变松；$\\lambda$ 偏小时逐步精度高，跳步时误差累积明显。工程上 $\\lambda$ 不是超参调优的重点，重点是它必须与跳步数一起定——4 步配方与 8 步配方的 $\\lambda$ 不应共用。</p>\n<p>关键推导一步在于把自洽项写成对两个时刻的联合期望。设 $t'$ 是 $t$ 沿 PF-ODE 前进（或后退）后的邻近时刻，一致性约束要求 $f_\\theta(x_{t'},t')$ 与 $f_\\theta(x_t,t)$ 在教师轨迹上指向同一终点，于是 <span class=\"formula\">$$\\mathcal{L}_{\\mathrm{cons}}=\\mathbb{E}_{t}\\big\\|f_{\\theta}(x_{t},t)-f_{\\theta}(x_{t'},t')\\big\\|^{2}$$</span>。注意这里没有出现 $x_0$：自洽项只用学生自己的两次前向，因此它可以在没有教师标注的 $x_{t'}$ 上采样，构成半监督式的正则。推导的实质是把“轨迹一致性”这一连续时间性质离散化到两个采样时刻上，$t'$ 的选取（等间隔还是按噪声调度非均匀）直接决定学生在哪些噪声段被压得最紧。</p>\n<p>代价落在训练侧而非推理侧：每个训练样本要跑一次教师 PF-ODE 得到 $x_0$，再加学生两次前向（$t$ 与 $t'$），单步计算量约为普通蒸馏的三倍。教师前向是 latent 空间的小分辨率 DiT，显存占用可控，但轨迹生成本身是 20–50 步的串行积分，教师侧吞吐成为蒸馏流水线的瓶颈，通常靠离线预生成 $(x_t,x_0)$ 配对缓存来摊薄。举例：一个 batch 内若 $t$ 采样落在高噪段，教师终点 $x_0$ 的结构信息弱、文本条件占主导，此时自洽项起主要作用；落在低噪段则端点回归项主导，学生被迫学会精细纹理。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-16\">十六 · CFG 并入条件嵌入的推导路径</h3>\n<p>标准 CFG 推理要跑两次前向：条件分支与无条件分支，再按引导尺度 $w$ 线性外插。蒸馏时把 $w$ 作为条件嵌入的一部分喂给学生，等价于把“两次前向的线性组合”折叠成“一次带 $w$ 输入的前向”。推导上，教师侧的组合是 <span class=\"formula\">$$\\hat{\\epsilon}=\\epsilon_\\theta(x_t,t,\\varnothing)+w\\left(\\epsilon_\\theta(x_t,t,c)-\\epsilon_\\theta(x_t,t,\\varnothing)\\right)$$</span>，学生要学的是映射 $(x_t,t,c,w)\\mapsto x_0$，其中 $w$ 进入条件嵌入的投影层。关键一步是把 $w$ 从标量升维成嵌入向量并与文本嵌入拼接，而不是简单乘在输出上——乘在输出上会让 $w$ 的调节退化为对 $x_0$ 的整体缩放，极端尺度下直接过饱和。</p>\n<p>系统代价的账很清楚：单次前向替代双 batch，显存与算力同时减半。以 DiT 为例，双 batch 意味着激活与 KV 类中间张量翻倍，CFG 蒸馏后这部分直接消失，批大小可以翻倍或留给 KV/特征缓存。但代价是引导强度的调节空间收窄：$w$ 被烘焙进条件嵌入后，推理时改 $w$ 需要重新走一次嵌入投影，且学生只在训练覆盖的 $w$ 区间内可靠。工程判断是给每个业务分层固定 1–2 个 $w$ 档位，把 $w$ 当作部署常量而非运行时旋钮，避免极端尺度下的结构塌陷。</p>\n<p>具体例子：长 prompt 场景下，条件分支的文本嵌入维度高、无条件分支几乎恒定，双 batch 的算力浪费在无条件分支上最严重；CFG 蒸馏后这部分浪费被彻底消除，单张图的 DiT 前向次数从 $2N_{\\text{step}}$ 降到 $N_{\\text{step}}$。这也是为什么 4–8 步配方在服务端的收益不止 4–8 倍时延，还叠加了约一半的算力节省。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-17\">十七 · 端到端时延公式与跳步的边界</h3>\n<p>端到端时延的分解是 <span class=\"formula\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$$</span>。这个式子看起来平凡，但它决定了优化的边际收益归属：当 $N_{\\text{step}}$ 从 20–50 降到 4–8，$N_{\\text{step}}\\cdot t_{\\text{DiT}}$ 项缩到原来的四分之一到八分之一，$t_{\\text{VAE}}$ 从次要项变成主导项。此时继续压步数的收益迅速衰减，而 VAE 解码的并行化（分块、多卡切分）成为下一段时延的主战场。反过来，若 VAE 解码本身很重，4 步与 6 步的端到端差异会被稀释，业务上不必为省两步牺牲画质。</p>\n<p>跳步的边界由噪声调度决定：4–8 个离散时间点不是均匀取，而是按 scheduler 的 $\\bar\\alpha_t$ 曲线在低噪段加密、高噪段稀疏。高噪步被跳过的理由是此时 latent 几乎纯噪声、结构信息尚未成形，教师在该段的贡献主要是全局布局，学生的一次前向足以覆盖；低噪段承载纹理与文字细节，必须保留足够密度。伪代码思路是：给定 $N_{\\text{step}}$，按 $\\bar\\alpha_t$ 等分信噪比区间取点，而非等分时间轴。这样做的代价是每个时间点的 $t$ 值不再规整，scheduler 更新需要按实际 $\\Delta t$ 缩放，实现上要把离散时间表作为常量表编译进 kernel 启动参数，避免运行时分支。</p>\n<p>具体例子：8 步配方在低噪段留 3 个点、高噪段留 2 个点、中段 3 个点，文字细节的退化主要出现在低噪点不足时；把低噪点从 2 增到 3、总步数不变，长 prompt 的字符可读性改善明显，而端到端时延不变。这就是“按业务分层选择步数”在调度表层面的落地方式。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-18\">十八 · 可实现的蒸馏伪代码</h3>\n<p>落到可实现，训练循环的骨架是：采样 $t$，用教师 PF-ODE 从 $x_t$ 积分得 $x_0^{\\text{tea}}$；学生前向 $f_\\theta(x_t,t,c,w)$ 得 $\\hat x_0$；再采样邻近 $t'$，取教师轨迹上对应的 $x_{t'}$，学生前向得 $\\hat x_0'$；损失为 $\\|\\hat x_0-x_0^{\\text{tea}}\\|^2+\\lambda\\|\\hat x_0-\\hat x_0'\\|^2$。实现要点有三：其一，$x_{t'}$ 必须来自同一教师轨迹，不能独立采样噪声再加噪，否则自洽项约束的是两条无关轨迹，退化为噪声正则；其二，$t'$ 与 $t$ 的距离要按跳步表设定，使学生在推理时会遇到的时间间隔上被训练；其三，CFG 的 $w$ 在训练时按区间随机采样，保证嵌入投影层覆盖部署档位。</p>\n<p>推理侧伪代码更短：载入离散时间表 $\\{t_i\\}$，latent 初始化为纯噪，循环 $i$ 从 0 到 $N_{\\text{step}}-1$：一次 DiT 前向得 $\\hat x_0$，按 scheduler 用 $\\hat x_0$ 与 $t_i,t_{i+1}$ 更新 latent；循环结束送 VAE 解码。注意每步只有一次 DiT 前向加一次 scheduler 更新，没有第二次前向做 CFG，也没有中间步的额外校正。这套结构不改推理框架，意味着它可以作为采样器插件挂进现有服务，与 NVFP4 量化、FA3 注意力叠加而不冲突——因为它们改的是数值格式与 kernel，本方法改的是步数与 CFG 结构。</p>\n<p>代价在冷启动：学生绑定教师架构，换底模必须重训，教师轨迹缓存也要重生成。工程上把蒸馏流水线做成“教师版本 + 跳步表 + $\\lambda$”三元组的产物，换底模时整条流水线重跑，旧学生不可复用，否则分布错配会导致画质崩坏而非渐进退化。这是本方法在容量规划上最容易被低估的一项：它不是一次训练，而是一个随底模版本走的持续成本。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-19\">十九 · 退化模式与分层步数的工程判据</h3>\n<p>少步采样的退化不是均匀的：文本复杂组合与细粒度文字生成退化最明显，因为这两类内容依赖低噪段的多步精修，而 4–8 步把低噪段的迭代次数压到个位数。判据是分层的：对细粒度文字要求高的业务（海报、UI 文案图）保 8 步甚至回退到更多步；对全局构图为主、文字仅作点缀的业务用 4–6 步。分层不是按请求随机选，而是按 prompt 长度与是否含文字指令做路由，路由表编译进调度器，避免运行时判断拖慢批处理。</p>\n<p>另一个退化源是 CFG 蒸馏后的极端尺度：$w$ 被烘焙进条件嵌入，超出训练覆盖区间时出现过饱和或结构塌陷。工程判断是把 $w$ 的运行时调节锁死在训练区间内，超出即拒绝或回落到最近档位，而不是让模型自由外插。这与量化里的校准区间是同一类思路：把不可靠的自由度收掉，换取可预测的输出分布。</p>\n<p>表格对比三种步数档位的取舍：</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>DiT 前向次数</th><th>时延相对基线</th><th>适用业务</th><th>主要退化</th></tr></thead><tbody><tr><td>4 步</td><td>4</td><td>约 1/8–1/5</td><td>全局构图、无文字</td><td>细节纹理偏软</td></tr><tr><td>6 步</td><td>6</td><td>约 1/5–1/3</td><td>一般文生图</td><td>长 prompt 组合偏差</td></tr><tr><td>8 步</td><td>8</td><td>约 1/4–1/3</td><td>含文字指令</td><td>字符边缘仍弱于 20 步</td></tr></tbody></table>\n<p>这张表的读法是：时延收益在 4 步处最陡，6 步之后边际收益变平，而画质在 8 步处才勉强覆盖文字场景。所以容量规划上应按业务分层分别定 GPU 配额，而不是全站统一压到 4 步——统一压步会把画质投诉集中到长 prompt 场景，反而拉高单位成本。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-20\">二十 · 与量化、注意力的叠加次序</h3>\n<p>本方法改的是采样步数与 CFG 结构，与数值格式、注意力 kernel 正交，因此叠加次序有讲究。推荐次序是：先定跳步表与 $\\lambda$（决定学生能力上限），再做 NVFP4/FP8 量化（决定单次前向的成本），最后调 FA3 类注意力（决定长序列下的带宽占用）。反过来先量化再蒸馏会让学生在不稳定的数值下学轨迹，自洽项被量化噪声污染，$\\lambda$ 需要重调。叠加后的端到端账是：$N_{\\text{step}}$ 缩小 4–8 倍、CFG 去掉一半前向、量化再压单次前向的算力与显存，三者相乘才是服务端的真实收益，而不是简单相加。</p>\n<p>一个具体机制上的注意点：TMEM 与 2-SM MMA 这类 Blackwell 特性改变的是单次 DiT 前向的内部结构，不影响跳步表的语义，但会改变 $t_{\\text{DiT}}$ 的量级，从而改变 $N_{\\text{step}}\\cdot t_{\\text{DiT}}$ 与 $t_{\\text{VAE}}$ 的相对权重。当 $t_{\\text{DiT}}$ 被压得很低时，VAE 解码占比上升，此时再压步数的收益已经很小，工程上应把优化预算转向 VAE 分块并行，而不是继续抠步数。这就是端到端公式给出的判断依据：优化要跟着当前主导项走，而不是跟着最熟悉的那个算子走。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-21\">二十一 · 失效边界与端到端代价账：一致性蒸馏不是免费午餐</h3>\n<p>把一致性约束写成可实现的损失，关键一步是让学生同时吃两个时间点：<div class=\"formula\">$$\\mathcal{L}=\\mathbb{E}\\big[\\|f_\\theta(x_t,t)-x_0\\|^2\\big]+\\lambda\\,\\mathcal{L}_{\\mathrm{cons}},\\quad \\mathcal{L}_{\\mathrm{cons}}=\\mathbb{E}_{t}\\big\\|f_\\theta(x_t,t)-f_\\theta(x_{t'},t')\\big\\|^2$$</div>第一项把任意轨迹点拉回教师 PF-ODE 终点，第二项强制相邻时刻映射自洽——若只有第一项，学生在训练分布外的时间点上会漂移，跳步时误差被放大；自洽项的作用是给跳步提供插值稳定性，λ 太小则 4 步轨迹抖动，λ 太大则拟合教师终点不足、细节变糊。这一项决定了伪代码里必须成对采样 t 与 t′，而不能只采单点。</p>\n<p>系统代价要按端到端算，而不是只看 DiT：<div class=\"formula\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$$</div>步数从 20–50 降到 4–8，DiT 部分线性缩小 4–8 倍，但 VAE 解码是固定项，分辨率越高、VAE 占比越大，端到端收益就越低于步数比。CFG 蒸馏把引导尺度并入条件嵌入，单次前向替代双 batch，显存与算力同时减半——这是少步方案在服务端真正的容量红利，但代价是引导强度调节空间收窄，极端尺度下易出现过饱和或结构塌陷，业务侧不能再靠调 CFG 救画质。</p>\n<p>失效条件集中在两类。其一是内容复杂度：少步采样对文本复杂组合与细粒度文字生成退化明显，长 prompt、多物体绑定、画面内文字这三类请求若不分层选择步数，画质投诉会集中爆发；工程上应按 prompt 长度与是否含文字渲染做路由，高要求请求回落到更多步或双阶段精修。其二是架构绑定：学生绑定教师架构，换底模必须重训，直接复用旧学生会导致分布错配与画质崩坏，冷启动成本构成规模上限。可与 NVFP4 量化、FA3 注意力叠加，因为它改的是步数与 CFG 结构而非数值格式，但量化误差与少步误差会叠加，需在分层策略里一并验证。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>标准扩散</th><th>少步一致性</th></tr></thead><tbody><tr><td>DiT 前向次数</td><td>20–50</td><td>4–8</td></tr><tr><td>CFG 前向</td><td>双 batch</td><td>并入条件嵌入，单次</td></tr><tr><td>显存/算力</td><td>基准</td><td>约减半</td></tr><tr><td>主要风险</td><td>时延与单位成本</td><td>文字/组合退化、换底模重训</td></tr></tbody></table>\n<h3 id=\"alg-lcm-fewstep-sec-22\">二十二 · 请求形态：什么流量吃得下少步采样</h3>\n<p>少步一致性采样改的是采样轨迹的离散点密度，因此它对请求形态的挑剔程度远高于对数值格式的挑剔程度。适配的请求形态有三个共同特征：条件信号短、语义约束松、单图价值密度低。典型如批量海报底图、商品场景图、社交配图、游戏概念草图、UI 占位插画——这类请求的 prompt 通常在十几个 token 量级，条件嵌入的语义带宽窄，4–8 步的一致性映射足以覆盖其条件流形。反过来，长 prompt、多实体空间关系、指定文字排版、精确品牌色与 logo 约束的请求，属于少步采样的结构性弱区：一致性学生把任意 $t$ 直接映射回 $x_0$，跳过了高噪段对全局布局的反复修正，条件信息在少步轨迹中只被消费 4–8 次，细粒度约束来不及在 latent 上收敛。</p>\n<p>工程上判断一条流量是否适配，看的是条件熵与步数的比值，而不是 prompt 字符数。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{fit}(q)=\\frac{H(c_q)}{N_{\\text{step}}},\\quad \\text{route}=\\begin{cases}\\text{few-step}, &amp; \\text{fit}(q)\\le \\tau\\\\ \\text{full-step}, &amp; \\text{fit}(q)&gt;\\tau\\end{cases}$$</div>\n<p>其中 $H(c_q)$ 是条件嵌入的语义熵代理量（可用 token 数、实体数、约束标签数的加权和估计），$\\tau$ 是分层阈值。这个路由判断必须落在网关层而非模型层，因为一旦请求进入 DiT 前向，步数就已经被固化。代价体现在容量上：若把长 prompt 流量误导入 4 步通道，画质投诉会集中在长 prompt 场景，返工重生成会把 GPU 时间翻倍消耗，等于把省下的 4–8 倍时延红利全部吐回去，还额外背上一次失败前向的显存占用。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-23\">二十三 · 长度分布：latent 分辨率与批内碎片</h3>\n<p>长度分布在这里指两件事：prompt token 长度的分布，以及输出 latent 分辨率的分布。前者决定条件分支的算力占比，后者决定 DiT 前向的激活显存与单步时延。少步采样把 $T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$ 中的 $N_{\\text{step}}$ 压到 4–8，于是 $t_{\\text{DiT}}$ 的权重相对上升，而 $t_{\\text{VAE}}$ 的占比被动放大——末端 latent 送 VAE 解码这一步在总时延中的份额从标准扩散的边角料变成不可忽略的固定开销。这意味着长度分布里的分辨率方差会直接放大批内碎片：同一批里混入高分辨率 latent，VAE 分块解码的块数上升，整批的尾延迟被这一张图拖住。</p>\n<p>因此负载配方要求按分辨率分桶，而不是按请求到达顺序组批。分桶后每桶内 latent 形状一致，DiT 前向的 tile 划分与 VAE 分块数固定，批内无碎片。代价是排队时延：分桶会牺牲到达序的即时性，低分辨率桶等待高分辨率桶凑批时，P99 时延由桶内最慢成员决定。工程判断是给每个桶设独立的批大小上限与最大等待窗口，宁可让高分辨率桶小批快跑，也不让低分辨率桶陪跑。举例：一个混合了 512 与 1024 latent 的到达流，若不分桶直接组批，1024 那张的 VAE 解码块数会把整批的完成时刻推后一个解码周期；分桶后两个桶各自在自己的 $N_{\\text{step}}$ 上收敛，尾延迟回到可控区间。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-24\">二十四 · 并发与批大小：CFG 蒸馏后的批几何</h3>\n<p>CFG 蒸馏把引导尺度并入条件嵌入，学生单次前向替代双 batch，这一步对负载配方的意义不是“省一半算力”这么简单，而是把批的几何从“条件批 × 2”变成“条件批 × 1”。标准扩散的 CFG 需要同一 latent 跑两遍条件与无条件分支，批大小实际是请求数的两倍；蒸馏后批大小等于请求数，显存与算力同时减半。于是同样的显存预算下，可容纳的并发请求数翻倍，连续批处理的调度窗口变宽，GPU 利用率曲线更平。</p>\n<p>但批大小不能无限放大。少步采样的每步 DiT 前向是整批同步的，批越大，单步 $t_{\\text{DiT}}$ 越长，而 $N_{\\text{step}}$ 只有 4–8，意味着整条请求的时延几乎完全由这几步的批同步时间决定，没有中间步可以掩盖长尾。批大小的上界由 SLO 反推：给定单步时延随批大小的增长曲线，取满足 $N_{\\text{step}}\\cdot t_{\\text{DiT}}(B)+t_{\\text{VAE}}\\le \\text{SLO}$ 的最大 $B$。这与标准扩散的批策略相反——标准扩散步数多，可以用后续步掩盖前面的批抖动；少步采样没有这个缓冲。</p>\n<p>并发侧的另一个代价是引导强度调节空间收窄。CFG 蒸馏后引导尺度被固化进条件嵌入，运行时改 scale 不再走双分支加权，而是走条件嵌入的插值或重编码，极端尺度下易出现过饱和或结构塌陷。负载配方上表现为：同一批内若混有不同引导强度的请求，条件嵌入需按请求逐一重编码，批内条件不一致会破坏 kernel 的规整性，单步时延上升。工程做法是把引导强度也作为一个分桶维度，与分辨率桶正交组合。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-25\">二十五 · 负载不对时的三种崩法</h3>\n<p>第一种是步数错配型退化。长 prompt、多实体组合、细粒度文字请求被塞进 4 步通道，一致性学生在高噪段的跳步让全局布局只被修正一次，文字区域的结构在 latent 上未收敛就被送进 VAE，输出表现为字形糊、笔画粘连、品牌色偏移。这类退化不是随机噪声，而是随文本复杂度单调上升的系统性偏差，投诉会集中出现在长 prompt 场景。代价是返工率上升，重生成请求把有效吞吐拉低，单位成本反而高于全步通道。</p>\n<p>第二种是学生-底模分布错配。蒸馏学生绑定教师架构，换底模必须重训。若运维侧为省冷启动成本直接复用旧学生挂到新底模上，学生的映射目标 $x_0$ 分布与教师 PF-ODE 终点分布不再对齐，一致性损失里的自洽项失效，输出出现整体色偏、结构塌陷甚至完全崩坏。这种失败在监控上表现为画质指标断崖式下跌而非渐进退化，排查成本高，因为推理框架、量化格式、注意力 kernel 都没变，唯一变量是底模版本。负载配方必须把学生版本与底模版本做成强绑定标签，路由层拒绝跨版本复用。</p>\n<p>第三种是批几何失配。CFG 蒸馏后批大小等于请求数，若调度器仍按旧的双 batch 逻辑预留显存，实际显存占用只有预算的一半，批大小被低估，GPU 利用率上不去；反之若按单 batch 逻辑放大批大小却没重算单步时延，SLO 会被尾延迟击穿。代价直接体现在显存与吞吐的错配上：显存闲置与 SLO 违约同时发生。工程判断是把批大小上界做成随 $N_{\\text{step}}$ 与分辨率桶动态重算的配置项，而不是静态常量。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-26\">二十六 · 配方落地：分层路由与桶化调度</h3>\n<p>把上述约束收拢成一份可执行的负载配方，核心是三张表：请求分层表、桶化调度表、版本绑定表。请求分层表按条件熵代理量把流量切成少步通道与全步通道，少步通道内部再按 4 步与 8 步两档细分——4 步给语义最松的批量底图，8 步给带中等约束的商业图。桶化调度表按 latent 分辨率与引导强度正交分桶，每桶独立批大小上限与等待窗口。版本绑定表把学生版本、底模版本、量化格式三者做成不可拆的组合键，路由层在入口处校验。</p>\n<p>调度器侧的伪代码思路是：到达请求先查分层表定 $N_{\\text{step}}$，再查桶化表定桶键，桶内凑批到上限或等待窗口到期即发车，发车前校验版本绑定键。代价是调度器状态变多，桶数与分层数的乘积决定队列数量，队列过多会让调度开销吃掉部分时延红利；工程上把桶数控制在个位数，分层控制在两档，用配置而非代码扩展。举例：一条以商品场景图为主的流量，条件熵低、分辨率集中在单一档位，配方退化为单桶单层，调度开销接近于零，4 步通道的时延红利全额兑现；而一条混合了海报底图与品牌文字图的流量，必须走双通道双桶，调度开销上升但返工率下降，净收益仍为正。</p>\n<p>最后落在具体机制上：少步采样的负载配方本质是把 $N_{\\text{step}}$ 从全局常量变成按请求条件分配的变量，而分配的依据是条件熵与分辨率桶，不是请求到达顺序。配方做对时，$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$ 里的 $N_{\\text{step}}$ 在每条请求上都取到其画质约束允许的最小值；配方做错时，省下的步数会被返工与尾延迟吃回去，且失败模式是系统性的而非随机的，监控上表现为长 prompt 场景的画质投诉密度与跨版本复用的画质断崖。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-27\">二十七 · 负载错配时的三重失效与配方边界</h3>\n<p>少步一致性采样把端到端时延压到 <span class=\"formula-inline\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$$</span> 的 4–8 步量级，但这条公式同时暴露了它的负载偏好：<span class=\"formula-inline\">$$t_{\\text{VAE}}$$</span> 是固定项，<span class=\"formula-inline\">$$N_{\\text{step}}\\cdot t_{\\text{DiT}}$$</span> 被压得很薄之后，VAE 解码在端到端时延中的占比被显著放大。于是最适合它的请求形态是短 prompt、单图、对细粒度文字与复杂空间组合要求不高的批量文生图——此时 GPU 时间几乎全花在 DiT 前向上，4–8 步的收益能完整兑现；反过来，长 prompt、多主体绑定、画面内文字渲染这类请求，恰恰是少步采样退化最集中的区间，画质投诉会成簇出现在长 prompt 场景，而不是均匀分布。</p>\n<p>并发与批大小的配方要按“每请求 DiT 前向次数”重算，而不是沿用标准扩散时代的批调度直觉。标准扩散每请求 20–50 次前向，连续批处理有充足的机会把不同请求的步拼进同一批次；少步方案每请求只剩 4–8 次前向，单请求在批内的驻留时间变短，批形成的窗口随之收窄，调度器若仍按旧的时间片切分，会出现批未填满就被迫发射的空泡。更关键的是 CFG 蒸馏把引导尺度并入条件嵌入，单次前向替代双 batch，显存与算力同时减半——这意味着同一张卡能容纳的并发请求数上升，但每个请求的算力需求下降，容量规划若按旧的双 batch 显存模型估算，会低估可并发数、高估单请求成本，SLO 达标率与单位成本的账同时对不上。</p>\n<p>失效条件里最硬的一条是学生绑定教师架构：换底模必须重训，直接复用旧学生会导致分布错配与画质崩坏，冷启动成本把规模上限锁在“教师架构不变”的范围内。另一条是 CFG 蒸馏后的引导强度调节空间收窄，极端尺度下易出现过饱和或结构塌陷，业务侧若把 guidance scale 当作可自由调的旋钮，就会撞上这条边界。工程判断是：把步数按业务分层配置——高价值、文字密集的请求回落到更多步或走标准扩散路径，低价值批量请求吃 4–8 步的红利；同时在调度层把“每请求前向次数”作为批形成的权重因子，而不是按请求数均分时间片。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>步数配方</th><th>主要系统代价</th></tr></thead><tbody><tr><td>短 prompt 批量文生图</td><td>4–8 步</td><td>VAE 解码占比上升，批窗口收窄</td></tr><tr><td>长 prompt / 细粒度文字</td><td>分层回退更多步</td><td>时延收益被稀释，画质投诉集中</td></tr><tr><td>换底模后复用旧学生</td><td>禁止，需重训</td><td>分布错配，画质崩坏</td></tr></tbody></table>\n<h3 id=\"alg-lcm-fewstep-sec-28\">二十八 · 硬件档位：按步数预算反推算力与显存</h3>\n<p>少步采样把端到端时延公式压缩成 <span class=\"formula\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$$</span> 之后，部署的第一件事不是选卡，而是判断 <span class=\"formula\">$$N_{\\text{step}}\\cdot t_{\\text{DiT}}$$</span> 与 <span class=\"formula\">$$t_{\\text{VAE}}$$</span> 谁占主导。当 N 从 20–50 压到 4–8，DiT 侧被削掉 4–8 倍，VAE 解码在端到端中的占比被动抬升，硬件档位的选择逻辑随之改变：过去按 DiT 峰值算力选卡，现在要按“DiT 短脉冲 + VAE 长尾”的混合负载选卡。工程上把档位分成三档来配：单卡档（单张 SM100 级 GPU，全部权重与 KV 驻留单卡，适合低并发、交互式出图）、单机多卡档（NVLink 5 域内 2–8 卡，DiT 走张量并行、VAE 独立占卡）、机架档（GB200/GB300 NVL72，把预填/解码或 DiT/VAE 拆到不同节点，靠 NIXL 传 latent）。判据是显存而非算力：少步采样下 DiT 前向次数少，算力利用率本就偏低，真正的约束是权重 + 激活 + latent 缓冲能否整块驻留，避免每步换入换出。若权重放不下而被迫分片，每步多一次跨卡 all-reduce，4 步就多 4 次同步，短脉冲的收益被通信吃掉。因此单卡档优先选显存足够容纳完整 DiT 与 VAE 的型号，多卡档只在单卡装不下时才启用，且并行度取最小可行值。</p>\n<p>具体例子：一个 4 步配置的请求，DiT 前向 4 次、每次几十毫秒量级，VAE 解码一次、耗时与分辨率强相关。若把 VAE 与 DiT 挤在同一张卡上串行执行，VAE 的长尾会直接暴露在 SLO 上；把 VAE 挪到第二张卡并用 NIXL 传末端 latent，DiT 卡在 VAE 解码期间即可接下一个请求的预填，尾延迟被流水掩盖。代价是跨卡 latent 传输的带宽开销与多一张卡的功耗预算，收益是 DiT 卡利用率从“等 VAE”变成“连续批处理”。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-29\">二十九 · 并行拓扑：DiT 张量并行与 VAE 分块的解耦</h3>\n<p>少步采样下 DiT 的并行策略要反着常规思路做。标准扩散 30 步时，张量并行的通信可以被 30 次前向摊薄；4 步时通信次数同比缩到 4 次，单次通信的相对成本上升，因此并行度不宜大。拓扑上推荐“DiT 小并行 + VAE 独立并行”的解耦结构：DiT 侧用 2 卡张量并行（TP=2）覆盖单卡装不下的情形，把每层的 all-reduce 控制在 NVLink 5 域内；VAE 侧按分块并行解码，块间无依赖，可独立扩到 2–4 卡而不影响 DiT 的通信节奏。两者之间只传一个末端 latent 张量，数据量小，用 NIXL 点对点传输即可，不需要集合通信。这样做的系统代价是：TP=2 使每步 DiT 多一次 all-reduce，若单步 DiT 时间被压到很短，通信占比会显著上升，因此 TP=2 只在单卡显存确实不足时启用；VAE 分块并行的代价是块边界的接缝处理与显存冗余，收益是把 VAE 长尾从关键路径上摘掉。</p>\n<p>伪代码思路：请求进入调度器后，先按 <span class=\"formula\">$$N_{\\text{step}}$$</span> 分层（简单 prompt 走 4 步、复杂组合走 8 步），4 步请求进 DiT 卡的低延迟队列，8 步请求进吞吐队列；DiT 完成末端 latent 后写入共享缓冲并触发 VAE 卡的解码任务，DiT 卡立即回到队列取下一个请求。调度参数上，连续批处理的最大批大小要按 DiT 单步显存余量反推，而不是按吞吐上限拍；因为 4 步请求的批处理窗口极短，批太大会把单请求的排队延迟推高，批太小又浪费 DiT 的算力。工程判断是：少步场景下批大小宜取中等偏小，用“多请求流水”而非“大 batch 填满”来维持 GPU 利用率。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-30\">三十 · 量化方案：与少步采样的叠加次序</h3>\n<p>少步采样改的是步数与 CFG 结构，不改数值格式，因此可与 NVFP4/FP8 量化叠加——但叠加有次序要求。量化误差在少步采样下被放大的机理是：一致性学生每步直接把 <span class=\"formula\">$$x_t$$</span> 映射回 <span class=\"formula\">$$x_0$$</span>，单步误差没有后续步的迭代修正机会，4 步内误差累积路径比 30 步短但每步权重大。因此量化方案要按“敏感层保精度、不敏感层压位宽”来配：DiT 的注意力投影与输出头对量化敏感，保留 FP8 或更高；FFN 与部分块可用 NVFP4。这与 DiT NVFP4 混合精度量化的分层思路同源，此处只强调叠加时的次序——先做 CFG 蒸馏把双 batch 合并成单次前向，再对单次前向的权重做量化校准，因为双 batch 与单 batch 的激活分布不同，按双 batch 校准出的 scale 用在单 batch 上会偏。系统代价上，NVFP4 把权重带宽需求压到 FP8 的一半左右，对少步采样尤其关键：4 步前向的权重读取次数少，单步内的权重带宽占比高，压位宽直接缩短单步 DiT 时间；代价是校准成本与画质退化，需按业务分层验证。</p>\n<p>具体例子：同一 4 步配置，FP8 权重下单步 DiT 受权重带宽约束，NVFP4 权重下带宽约束放松、单步时间下降，但细粒度文字区域的退化会更早出现。工程做法是对走 4 步的简单 prompt 用 NVFP4，对走 8 步的复杂组合 prompt 保留 FP8，按调度分层切换精度档——这要求框架支持同一模型的多精度副本共存，显存代价是两份权重，收益是画质与吞吐的分层兑现。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-31\">三十一 · KV 策略：少步场景下 KV 的真实角色</h3>\n<p>扩散推理没有自回归解码那种逐 token 增长的 KV cache，但 DiT 的注意力在每个去噪步内仍需对 latent 序列做自注意力，序列长度由分辨率与 patch 化决定。少步采样把步数压到 4–8，跨步复用注意力的机会变少，KV 策略的重点从“跨步缓存”转向“步内分块与显存复用”。可用的机制是：把每步的 K/V 计算与注意力分块绑定，块级计算完即释放，避免为整段序列常驻 K/V 缓冲；对 8 步请求可选择性保留低噪步的 K/V 供后续步复用，对 4 步请求则不复用，因为复用窗口太短、命中率不足以抵消缓存管理开销。系统代价是：保留 K/V 会占用显存，挤占连续批处理的批大小空间；不保留则每步重算 K/V，增加算力开销。判据是显存余量与步数的组合——显存紧张时优先不缓存，用算力换显存；显存充裕且步数为 8 时，缓存低噪步 K/V 可减少重复计算。</p>\n<p>与特征缓存与块级跳步的关系是一句话指路：那是跨步跳过的另一条路径，本节的 KV 策略只解决步内注意力的显存驻留问题。工程判断上，少步采样的 KV 策略应默认“无跨步缓存 + 步内分块释放”，把显存留给更大的批大小，因为 4–8 步的复用收益本就有限，而批大小对吞吐的边际贡献更直接。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-32\">三十二 · 调度参数：分层步数与 SLO 的耦合</h3>\n<p>调度参数的核心是把“步数分层”做成可执行的队列策略，而不是让所有请求共用一套参数。机制上，调度器在请求入口按 prompt 复杂度打标：短 prompt、常见组合走 4 步低延迟队列；长 prompt、细粒度文字需求走 8 步吞吐队列；两队列共享 DiT 卡但分配不同的批大小与优先级。公式上，单请求的 SLO 约束可写成 <span class=\"formula\">$$T_{\\text{e2e}}=N_{\\text{step}}\\cdot t_{\\text{DiT}}(B)+t_{\\text{VAE}}\\le T_{\\text{SLO}}$$</span>，其中 <span class=\"formula\">$$t_{\\text{DiT}}(B)$$</span> 随批大小 B 上升，因此 4 步队列的批大小上限由最严 SLO 反推，8 步队列的批大小上限由吞吐目标反推。系统代价是：两队列共存需要显存容纳两套批缓冲，且精度档切换（NVFP4 与 FP8 副本）进一步占显存；收益是把画质投诉集中到长 prompt 场景的可预期范围内，而不是让 4 步请求替 8 步请求背锅。</p>\n<p>具体例子：一个混合负载的服务，4 步队列的请求占多数、SLO 紧，8 步队列的请求少但单请求耗时长。若不分层，调度器按统一批大小跑，4 步请求被 8 步请求拖长排队，8 步请求又被大 batch 拖慢单步时间，两头不讨好。分层后，4 步队列用小批快跑、8 步队列用大批慢跑，DiT 卡在两队列间按权重轮转，VAE 卡按 latent 到达顺序解码。调度参数上还要设一个步数降级阈值：当 8 步队列积压超过阈值时，把部分请求降到 4 步并标记画质降级，用可接受的退化换 SLO 达标——这是少步采样特有的弹性手段，因为步数本身就是调度变量。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-33\">三十三 · 可复现配置思路：从约束到参数的推导链</h3>\n<p>把上述五节收成一条可复现的推导链，顺序是：先定 SLO 与业务分层，再定步数分层，再定精度档，再定并行拓扑，最后定批大小与 KV 策略。第一步，按业务把请求分成“4 步可接受”与“必须 8 步”两层，给出各自的 SLO；第二步，用 <span class=\"formula\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$$</span> 反推单步 DiT 的时间预算，若预算不足以容纳目标批大小，则先压精度档（FP8→NVFP4）再考虑加卡；第三步，按单卡显存判断 DiT 是否需要 TP=2，能单卡则单卡，避免 4 步下的通信占比上升；第四步，把 VAE 独立到第二张卡或分块并行，用 NIXL 传 latent，把 VAE 长尾从关键路径摘掉；第五步，4 步队列取小批、8 步队列取大批，KV 默认步内分块释放、不跨步缓存；第六步，设步数降级阈值与精度档切换规则，作为过载时的弹性阀。</p>\n<p>这条链的每一步都有明确的代价锚点：压精度档换带宽与单步时间，代价是画质退化；加卡换显存与并行，代价是通信与功耗；VAE 独立换流水掩盖，代价是跨卡传输；分层调度换 SLO 达标，代价是显存冗余与实现复杂度。可复现的关键不是某一组具体数字，而是这条“约束→预算→档位→参数”的推导次序：任何一组硬件与 SLO 输入，都能沿同一次序推出配置，而不需要凭经验拍参数。工程判断落在最后一步——少步采样的部署弹性来自步数本身可调，把步数当作调度变量而非固定常量，是这套配置思路与标准扩散部署最本质的区别。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-34\">三十四 · 少步配方的边界：何时该退回多步、何时必须重训</h3>\n<p>把 4–8 步配方推上生产，第一件要钉死的不是吞吐，而是<b>分层路由</b>。少步采样在长 prompt、多实体组合与画面内文字上退化明显，退化不是均匀的：短 prompt 与单主体场景下 4 步即可交付，而含精确文字、空间关系约束的请求，即便给到 8 步也难保结构正确。工程上应把步数作为请求级参数暴露给调度器，按 prompt 复杂度（token 数、实体计数、是否含文字渲染标记）分档，而不是全局固定一个步数。代价是调度器要为同一模型维护多条时间预算曲线，且分档阈值需用线上投诉回流持续校准——否则画质投诉会集中爆发在长 prompt 场景，而监控面板上的平均时延依旧漂亮。</p>\n<div class=\"formula\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}},\\quad N_{\\text{step}}\\in\\{4,6,8\\}$$</div>\n<p>由上式可见，步数降到 4 后，VAE 解码在端到端时延中的占比显著上升，继续压 DiT 步数的边际收益迅速衰减；此时优化重心应从采样循环转向 VAE 解码与 latent 传输。另一条硬边界是<b>架构绑定</b>：一致性学生与教师架构强耦合，换底模必须重训，直接复用旧学生会导致分布错配与画质崩坏。因此部署配方里必须预留一条“教师版本—学生版本”的配对校验链路，推理服务启动时校验权重指纹，不匹配即拒绝加载，避免灰度期间静默降质。</p>\n<p>CFG 蒸馏把引导尺度并入条件嵌入，换来单次前向替代双 batch，显存与算力同时减半——这是少步方案能在单卡上跑起更大批次的根本原因。但它收窄了引导强度的可调空间：极端尺度下易出现过饱和或结构塌陷，运营侧若沿用旧版可调 CFG 的交互习惯，会直接触发这类失败。配方上应把引导尺度固化为蒸馏时的取值，仅在有限档位内提供微调，并在前端明确其调节范围。与 NVFP4 量化、FA3 注意力叠加时，少步配方改的是步数与 CFG 结构而非数值格式，二者可正交组合；但量化误差在少步下缺少后续步的误差修正机会，需在 4 步档位单独做画质回归，不能沿用 30 步档位的量化标定结论。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>步数</th><th>主要风险</th><th>系统代价</th></tr></thead><tbody><tr><td>短 prompt / 单主体</td><td>4</td><td>低，量化误差主导</td><td>VAE 解码占比上升</td></tr><tr><td>多实体组合</td><td>6</td><td>结构错位</td><td>时延线性增加</td></tr><tr><td>含文字渲染</td><td>8 或回退多步</td><td>文字糊化、笔画崩坏</td><td>吞吐回落，需独立队列</td></tr></tbody></table>\n<h3 id=\"alg-lcm-fewstep-sec-35\">三十五 · 少步之后，瓶颈从 DiT 前向挪到别处</h3>\n<p>把 $T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$ 里的 $N_{\\text{step}}$ 从 20–50 压到 4–8，最先变化的不是总时延，而是时延的<strong>构成比例</strong>。原来 $t_{\\text{DiT}}$ 占绝对主导，工程优化的全部注意力都在 DiT 的 GEMM 与注意力 kernel 上；少步之后 DiT 部分被压缩 4–8 倍，VAE 解码、latent 搬运、请求排队与调度开销的相对份额被抬到不可忽略的位置。这意味着在 Blackwell 上继续给 DiT 做 NVFP4 量化或 FA3 异步注意力的边际收益被稀释——单步 DiT 再快 20%，若只占端到端 40%，端到端只快 8%。系统代价的核算必须换成\"每张图固定开销 + 每步可变开销\"的两段式：固定开销包括 VAE 解码、latent 显存往返、请求级调度与结果回传；可变开销才是 $N_{\\text{step}}$ 次 DiT 前向。少步采样的真正工程含义是：它把系统从\"算力受限\"推向\"固定开销受限\"，于是优化重心从 kernel 转向流水与显存。</p>\n<p>具体机制上，一致性学生每次前向的输入是 $x_t$ 与离散时间点 $t$，输出直接是 $x_0$ 估计，scheduler 更新退化为一次跳步赋值而非多阶求解。伪代码层面：<code>for t in {t_1..t_K}: x = student(x, t, cond); x = jump(x)</code>，$K\\in[4,8]$。每步只有一次 DiT 前向，没有 CFG 双 batch，因此单请求的算力峰值下降一半，但每步之间的依赖是严格的串行链——第 $k$ 步的输出是第 $k+1$ 步的输入，无法在单请求内部并行。这决定了少步采样的吞吐上限不由单请求时延决定，而由<strong>能同时驻留多少个请求的串行链</strong>决定，也就是显存与批调度。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-36\">三十六 · 显存：激活峰值降了，KV 式缓存没有，但驻留请求数才是关键</h3>\n<p>CFG 蒸馏把引导尺度并入条件嵌入，学生单次前向替代双 batch，这一步对显存的直接效果是激活峰值减半——原来 CFG 需要两份 latent 与两份注意力中间结果并行推进，现在只有一份。但少步采样并不产生类似自回归解码的 KV cache 结构，扩散的\"缓存\"是特征缓存与块级跳步那一类跨步复用的东西，属于另一条优化线。因此在显存账本上，少步采样的贡献是<strong>降低单请求瞬时激活</strong>，而不是降低单请求常驻状态。真正决定吞吐的是：单请求在 4–8 步串行链上占用的显存能否被更多并发请求分摊。</p>\n<p>代价核算可以写成：设单请求激活峰值为 $A$、模型权重与 workspace 为 $W$、可用显存为 $M$，则并发驻留上限 $B_{\\max}\\approx (M-W)/A$。CFG 蒸馏让 $A$ 减半，$B_{\\max}$ 近似翻倍；但少步采样把每请求的 GPU 占用时间压到原来的 $1/(4\\text{–}8)$，于是同样的 $B_{\\max}$ 下单位时间能消化的请求数上升得更快。这里的工程判断是：在 B200/GB200 这类大显存档位上，少步采样的显存收益主要体现为\"能把 batch 拉大\"，而不是\"能跑更大的模型\"。反过来，若框架仍按 20–50 步的旧配方预留激活 buffer 与调度窗口，少步带来的显存红利会被静态分配吃掉，表现为显存利用率低而吞吐不涨。</p>\n<p>具体例子：一个按 30 步、CFG 双 batch 配置的服务实例，其激活预留按最坏步的峰值设定；切换到 6 步、CFG 蒸馏学生后，若不改预留，显存占用几乎不变，但每请求驻留时间降到约五分之一，调度器若仍按旧并发上限放行，GPU 会出现\"显存满、SM 闲\"的空转。修正动作是把并发上限按新的 $A$ 重算并放开，让更多请求的串行链交错填满 SM。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-37\">三十七 · 带宽与通信：少步放大的是权重搬运占比，不是单步算术强度</h3>\n<p>单步 DiT 前向的算术强度不因少步而改变，改变的是<strong>权重读取与激活读写的比例</strong>。步数减少意味着每张图摊到的权重搬运次数减少，但每步仍要把整份 DiT 权重从 HBM 过一遍（或在 TMEM/共享内存里分块复用）。当 $N_{\\text{step}}$ 从 30 降到 6，权重搬运总量降为五分之一，HBM 带宽压力同步下降——这是少步采样在带宽账本上的正收益。但它同时把 VAE 解码与 latent 往返的相对带宽份额抬高：末端 latent 送 VAE 解码这一步的显存读写不再被 DiT 的长链掩盖，成为固定开销的一部分。</p>\n<p>通信侧要区分两种规模。单卡或单请求内，少步采样不引入新的集合通信，串行链上没有 all-reduce 需求。多卡张量并行或分离式预填/解码部署下，每步 DiT 前向仍带一次层间 all-reduce 或 all-gather，步数减少直接把通信次数按比例削减——这是少步采样对 NVLink 5 拓扑最直接的减负。但要注意一个反向效应：少步之后单步的计算时间变短，通信的<strong>相对</strong>占比上升，若并行切分过细，单步内 all-reduce 的固定延迟会吃掉步数缩减的收益。工程判断是：少步配方下应倾向更粗的并行切分与更大的本地 batch，用计算把通信延迟盖住，而不是沿用 30 步时代为压单步时延而做的细粒度切分。</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx \\max\\!\\left(t_{\\text{GEMM}}+t_{\\text{attn}},\\; t_{\\text{comm}}\\right),\\quad \\text{有效加速}\\approx \\frac{N_{\\text{old}}\\cdot T_{\\text{step,old}}}{N_{\\text{new}}\\cdot T_{\\text{step,new}}}$$</div>\n<p>若 $t_{\\text{comm}}$ 在少步配方下逼近 $t_{\\text{GEMM}}+t_{\\text{attn}}$，则分母不再随 $N_{\\text{new}}$ 线性缩小，实际加速比会低于名义的 4–8 倍。这是规模上去以后通信侧最先暴露的失真。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-38\">三十八 · 功耗与能效：空转与固定开销决定单位图成本</h3>\n<p>功耗账本在少步采样下出现一个容易被忽略的结构性变化：DiT 的长时间高利用率区间被压缩，GPU 在请求间隙进入低利用率的机会变多。若调度器不能把请求的串行链紧密交错，SM 占用率会呈现\"短脉冲 + 长空窗\"的形态，功耗下降但能效（每焦耳产出的图数）反而变差——因为固定开销（VAE、搬运、调度）在低占用下效率更低。少步采样的能效收益只有在<strong>高并发交错</strong>时才兑现：多条 4–8 步的串行链同时在 SM 上推进，把 DiT 脉冲之间的空隙填满，让 GPU 维持在高占用高效率区间。</p>\n<p>具体机制上，连续批处理式的调度在这里的作用不是批处理本身，而是把不同请求的第 $k$ 步对齐到同一批 GEMM 里，使每步的算术强度不因批小而塌陷。代价是调度窗口变长：为了凑批，单请求可能等待，尾延迟上升。这与少步采样\"单请求很快\"的直觉相反——单请求快不等于系统快，系统吞吐由批的填充率决定。功耗侧的判断是：少步配方应与更大的批和更激进的并发上限配对，否则省下的算力会以空转的形式浪费掉，单位图成本不降反升。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-39\">三十九 · 尾延迟：串行链短了，但排队与固定开销成了新尾巴</h3>\n<p>尾延迟在少步采样下的形态变化值得单独拆开。单请求的执行时间被压到 4–8 步，其方差主要来自固定开销而非步数——VAE 解码的耗时与 latent 尺寸相关，与步数无关，因此在短请求里它的占比被放大，成为 P99 的主要贡献项。更关键的是排队：当并发上限被放开、批被拉大，单请求在调度队列里的等待时间可能超过其执行时间本身。于是尾延迟的构成从\"执行慢\"变成\"等得久\"，这是少步采样在规模上最先崩的地方之一。</p>\n<p>具体例子：长 prompt 与复杂组合的请求在少步配方下画质退化明显，业务侧会触发重试或升步数重跑，这类请求的执行时间反而变长，并且集中在尾部分布。若不分层选择步数，尾延迟会被这批\"降级重跑\"请求拉高，同时画质投诉集中出现在长 prompt 场景——两个问题同源。工程上应把步数分层做成请求级策略：简单 prompt 走 4 步，复杂组合走 6–8 步，并在 SLO 里为不同分层设不同的尾延迟目标，而不是用一个统一的步数配置去覆盖全部流量。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-40\">四十 · 规模上去以后，先崩的是调度与冷启动，不是 kernel</h3>\n<p>把规模推上去，少步采样的系统瓶颈排序大致是：先是调度与批填充率，然后是 VAE 与 latent 搬运的固定开销，再是通信的相对占比，最后才是单步 kernel 效率。原因在于少步采样已经把可变开销压得很薄，剩下的都是与步数无关的项，它们不随规模摊薄，只随并发结构变化。规模越大，这些固定项在总成本里的份额越稳定，越难靠\"再多加几张卡\"解决。</p>\n<p>另一个先崩的点是冷启动与模型绑定。蒸馏学生绑定教师架构，换底模必须重训，冷启动成本高；直接复用旧学生会导致分布错配与画质崩坏。在多业务、多底模的服务集群里，这意味着每个底模都要维护一套学生权重与对应的步数分层配置，显存里驻留的模型副本数上升，权重换入换出的带宽开销也随之上升。规模上去后，权重驻留与换入策略会比单步 kernel 更早成为容量规划的约束。CFG 蒸馏把引导尺度并入条件嵌入后，引导强度调节空间收窄，极端尺度下易出现过饱和或结构塌陷，这进一步限制了用运行时调参去补救画质退化的空间——只能靠分层与重训，而重训是冷启动成本。</p>\n<p>工程判断落在具体机制上：把少步采样当成\"步数参数\"来调是错的，它是一套绑定教师、绑定分层、绑定调度窗口的系统配方。规模化的正确动作是先把并发上限与批填充率按新的激活峰值重算，再把步数分层写进请求路由，最后才去动 kernel——因为在少步配方下，前两步的收益远大于第三步，而第三步的边际收益已经被 $N_{\\text{step}}$ 的缩减稀释。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-41\">四十一 · 少步之后，瓶颈从 DiT 前向挪到了别处</h3>\n<p>把 <span class=\"formula\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$$</span> 里的 <span class=\"formula\">$$N_{\\text{step}}$$</span> 从 20–50 压到 4–8，收益并不是均匀摊在每一段上的：DiT 前向那一段按比例缩短，而 VAE 解码、请求排队、latent 搬运这些与步数无关的项原地不动。于是端到端时延的构成发生翻转——原先 DiT 占大头，少步之后 VAE 解码与调度开销的占比显著上升，继续优化 DiT kernel 的边际收益迅速衰减。工程判断很直接：少步方案上线后，性能剖析的重心应从 MMA 利用率转向 VAE 解码吞吐与批调度粒度，否则会出现“步数降了 6 倍、端到端只降了 3 倍”的落差。CFG 蒸馏把双 batch 合成单次前向后，单请求的显存与算力同时减半，这直接抬高了单卡可容纳的并发批大小；但批变大之后，尾延迟由批内最慢的那条请求决定，长 prompt 与复杂组合请求恰好是少步采样画质最先退化、也最容易被重试或人工复核的那一类，尾延迟反而被拉长。</p>\n<p>规模上去以后先崩的位置，通常不是算力而是通信与显存带宽。少步采样让单请求的 DiT 计算量下降，但每步仍要读写完整的 latent 激活与注意力中间结果，单位时间内的请求数上升意味着这些访存操作的密度上升；在多卡并行拓扑下，若采用序列或 latent 切分，每步的 all-reduce/all-gather 次数并不随步数减少而减少，通信开销在总时延中的占比被放大。用一个小表看清代价迁移的方向：</p>\n<table class=\"mini\"><thead><tr><th>代价项</th><th>20–50 步时</th><th>4–8 步后</th></tr></thead><tbody><tr><td>DiT 前向</td><td>主导项，随步数线性</td><td>压缩 4–8 倍，退居次席</td></tr><tr><td>CFG 双 batch</td><td>显存与算力翻倍</td><td>蒸馏并入条件嵌入，减半</td></tr><tr><td>VAE 解码</td><td>占比小</td><td>占比显著上升，成为新瓶颈</td></tr><tr><td>跨卡通信</td><td>被长计算掩盖</td><td>暴露为可见开销</td></tr></tbody></table>\n<p>功耗与容量规划也要跟着改口径。少步采样提高了单位时间的请求吞吐，GPU 从“长时间高占用算一个请求”变成“短时高频切换请求”，功耗曲线更陡、更碎，功率封顶（power capping）下的频率抖动对尾延迟的影响比稳态长计算时更敏感。容量规划不能再用“单请求时延×并发数”的旧模型，而要把 VAE 解码、通信、调度排队单独建模，按业务分层给出不同的步数档位：对细粒度文字与复杂组合要求高的请求保留较高步数，其余走 4–8 步快车道。最后要盯住的是绑定成本——学生网络绑定教师架构，换底模必须重训，冷启动成本高；直接复用旧学生会导致分布错配与画质崩坏，这类失效在规模扩张、底模迭代频繁的阶段最容易集中爆发，且无法靠加卡或调批大小掩盖。</p>\n<h3 id=\"alg-lcm-fewstep-sec-42\">四十二 · 精度退化：少步映射的误差放大与分层诊断</h3>\n<p>少步一致性采样把 20–50 步的 PF-ODE 轨迹压缩到 4–8 个离散时间点，误差不再被多步迭代摊薄，而是被单次映射直接放大。核心机制在于：学生网络在 $t$ 处一次性预测 $x_0$，任何条件嵌入的微小偏移都会沿 latent 通道传播到 VAE 解码端。诊断时不要只看整图 FID 类指标，应按 prompt 结构分层切片——单主体、多主体组合、含文字区域、长 prompt——分别统计退化率。工程上把退化归因为三类：条件嵌入偏移（CFG 蒸馏后引导尺度并入嵌入，极端尺度下过饱和或结构塌陷）、时间点离散化误差（4 步时相邻 $t$ 间隔过大，scheduler 更新项被跳过）、教师-学生分布错配（换底模未重训）。</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\text{cons}}=\\mathbb{E}_{t}\\big\\|f_{\\theta}(x_{t},t)-f_{\\theta}(x_{t'},t')\\big\\|^{2},\\quad T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$$</div>\n<p>公式右侧的 $N_{\\text{step}}$ 是诊断的旋钮：把步数从 4 提到 6 或 8，$T_{\\text{e2e}}$ 线性上升但退化率下降，这条曲线就是分层路由的依据。代价侧要算清楚：每多一步 DiT 前向，单请求算力与显存带宽占用按比例上升，而 VAE 解码的 $t_{\\text{VAE}}$ 不变，因此步数增加的边际时延成本在高分辨率下被稀释、在低分辨率下更显著。具体例子：一条含品牌文字的长 prompt 在 4 步下文字区域糊化，切到 8 步后文字可读但端到端时延翻倍，此时应把该 prompt 类目路由到 8 步通道而非全局提步。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-43\">四十三 · OOM 与显存抖动：CFG 蒸馏后的隐性峰值</h3>\n<p>CFG 蒸馏把双 batch 合并为单次前向，名义显存减半，但 OOM 往往出现在别处：批内最长 prompt 的交叉注意力激活、VAE 分块解码的临时缓冲、以及调度器为吸收批抖动而预留的 KV/激活池。机制上，连续批处理在等待新请求拼批时会持有已完成请求的 latent 直到 VAE 释放，若解码慢于 DiT 前向，latent 队列堆积造成显存尖峰。诊断手段是给激活分配打标签采样，区分 DiT 激活、VAE 缓冲、调度器预留三块，观察峰值出现在哪一段。</p>\n<ul>\n<li>触发条件一：批大小按平均序列长度配置，遇到长 prompt 时交叉注意力激活超预算。</li>\n<li>触发条件二：VAE 分块并行解码的块数固定，高分辨率请求使单块缓冲膨胀。</li>\n<li>触发条件三：路由到 8 步通道的请求与 4 步请求混批，步数差异导致批内生命周期不齐，调度器为等慢请求而延长持有。</li>\n</ul>\n<p>代价判断：OOM 重试一次意味着整批请求的 DiT 前向作废，吞吐损失等于批大小乘以单步时延；更隐蔽的是显存碎片化，长期运行后可用块不足以拼出目标批，吞吐缓慢下滑而非硬崩。具体例子：同一节点上 4 步与 8 步请求混跑，8 步请求占住 latent 队列，4 步请求完成后无法释放，峰值显存超出单通道配置，解决方式是按步数通道隔离批队列，而非简单调低批大小。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-44\">四十四 · 批抖动与路由不均：步数通道的负载守恒</h3>\n<p>分层步数路由引入了一个新问题：4 步通道吞吐高、8 步通道吞吐低，若路由比例随流量波动，两条通道的 GPU 利用率会反向漂移。机制上，路由器按 prompt 复杂度打分决定步数，打分本身有延迟且分布随业务时段变化，导致通道间请求量不守恒。诊断指标应包含每条通道的排队长度、批填充率（实际批大小与目标批大小之比）、以及跨通道的等待时间差。批填充率低于阈值说明拼批不足，算力被浪费；等待时间差扩大说明路由倾斜。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>机制归因</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>4 步通道空闲、8 步通道排队</td><td>路由打分偏向高复杂度</td><td>整体吞吐受慢通道拖累</td><td>按通道配额限流，溢出请求降级到 6 步</td></tr><tr><td>批填充率持续偏低</td><td>请求到达间隔大于拼批窗口</td><td>单请求算力成本上升</td><td>拉长拼批窗口，代价是首 token 时延</td></tr><tr><td>通道间等待差抖动</td><td>流量时段性偏移</td><td>尾延迟尖刺</td><td>动态调整路由阈值而非固定比例</td></tr></tbody></table>\n<p>具体例子：白天长 prompt 占比升高，路由把大量请求推入 8 步通道，4 步通道 GPU 利用率掉到低位，此时若简单扩容 8 步通道，夜间流量反转又造成反向浪费；正确做法是把路由阈值做成随窗口统计自适应，并保留 6 步作为缓冲档。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-45\">四十五 · 尾延迟尖刺：VAE 与调度器的耦合点</h3>\n<p>端到端时延由 $N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$ 构成，少步采样把 DiT 段压短后，VAE 段在总时延中的占比上升，尾延迟尖刺更容易由 VAE 触发。机制上，VAE 分块解码的块间并行度受显存约束，高分辨率请求的块数多、单块耗时长，若与 DiT 前向共享 SM 资源，会出现互相抢占。诊断要采集分位延迟（p50/p90/p99）并按分辨率与步数交叉切片，定位尖刺是来自 DiT 步数通道还是 VAE 块调度。</p>\n<ul>\n<li>尖刺来源一：VAE 块调度等待显存释放，表现为 p99 远高于 p50 而 p50 稳定。</li>\n<li>尖刺来源二：批内混入高分辨率请求，整批 DiT 前向被拉长，表现为批级延迟同步抬升。</li>\n<li>尖刺来源三：路由切换瞬间的冷启动，新通道首批请求未填满，单请求承担全部固定开销。</li>\n</ul>\n<p>代价判断：尾延迟尖刺对 SLO 的伤害是非线性的，p99 超标即触发告警与降级，而降级本身（切回更多步数或降低分辨率）又进一步拉长时延，形成正反馈。具体例子：某时段 p50 稳定但 p99 跳升，切片后发现全部落在高分辨率加 8 步通道的交集，处置是把高分辨率请求的 VAE 解码与 DiT 前向做资源隔离，而非提高整体步数。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-46\">四十六 · 监控与回滚：把诊断信号做成可执行开关</h3>\n<p>监控体系要围绕三个可观测面：画质退化率（按 prompt 分层采样人工或自动评分）、资源面（显存峰值、批填充率、通道利用率）、时延面（分位延迟按通道切片）。机制上，把每个信号绑定一个回滚动作：退化率超阈值则把该 prompt 类目从 4 步升到 6/8 步；显存峰值逼近上限则隔离批队列或降低 VAE 块并行度；尾延迟尖刺则临时收紧路由阈值。回滚必须是配置级而非代码级，保证分钟级生效。</p>\n<div class=\"formula\">$$\\text{rollback}=\\begin{cases}\\text{step}\\uparrow &amp; \\text{if } \\text{degrade}(c)&gt;\\tau_d\\\\ \\text{batch}\\downarrow &amp; \\text{if } \\text{mem}_{\\text{peak}}&gt;\\tau_m\\\\ \\text{route}\\rightarrow\\text{conservative} &amp; \\text{if } p99&gt;\\tau_l\\end{cases}$$</div>\n<p>代价侧要预先算清回滚的吞吐损失：步数从 4 升到 8 使 DiT 段时延翻倍，批大小下调使单请求算力成本上升，两者叠加可能让单位成本超出预算，因此回滚阈值应留出缓冲带而非贴着 SLO 设。具体例子：换底模后旧学生直接复用导致分布错配、画质崩坏，监控在退化率上先于用户投诉捕获信号，回滚动作是切回旧底模的已蒸馏学生并冻结新路由，同时触发重训流程——冷启动成本高这一约束决定了回滚必须保留上一版学生常驻。</p>\n<p>最后落在工程判断上：少步一致性采样的失败模式大多不是单点故障，而是路由、批、显存、VAE 四者耦合后的系统性漂移，诊断的价值在于把漂移定位到具体通道与具体资源段，回滚的价值在于用配置开关在分钟级切断漂移传播，而重训成本决定了版本切换必须双版本并行而非原地替换。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-47\">四十七 · 少步采样的失效边界：从画质退化到路由塌陷</h3>\n<p>少步一致性采样的失效不是单点故障，而是沿三个方向同时收窄：文本复杂度、底模绑定、CFG 尺度。第一类是画质退化，长 prompt 与细粒度文字生成在 4–8 步下最先崩，因为一致性映射把整条 PF-ODE 轨迹压缩成少数几个离散跳点，高频细节与组合约束在跳步中被抹平；此时端到端时延仍按 <span class=\"formula\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$$</span> 线性下降，但 VAE 解码与 DiT 前向的占比会随步数减少而反转——步数降到 4 时 VAE 成为时延主项，继续压步数的边际收益迅速衰减。第二类是分布错配，蒸馏学生绑定教师架构，换底模不重训就直接复用旧学生，输出分布与教师轨迹脱节，表现为画质整体崩坏而非局部退化，这类故障在监控上呈现为整批请求的 CLIP 分数同步下移，而不是零散尖刺。</p>\n<p>第三类是 CFG 蒸馏带来的引导空间收窄。引导尺度被并入条件嵌入后，学生单次前向替代双 batch，显存与算力同时减半，但推理期可调的引导强度范围变窄，极端尺度下出现过饱和或结构塌陷。诊断上应把引导尺度作为独立维度打点，按尺度分桶统计过饱和率与结构异常率，而不是只看全局均值；一旦某个尺度桶的异常率抬升，说明该业务分层的步数配方与引导嵌入不匹配，需要回退到更高步数档而非调尺度。批抖动与 OOM 则来自另一条链路：CFG 蒸馏省掉双 batch 后显存余量变大，调度器倾向放大批，但少步采样使单请求驻留时间缩短，批内请求的完成时刻更集中，VAE 解码阶段的显存峰值与 DiT 阶段的峰值错开，形成周期性抖动；监控应采集每批的显存高水位与批完成间隔的方差，方差抬升即预警。</p>\n<p>尾延迟尖刺与路由不均通常同源。少步采样把单请求时延压到很低，负载均衡若仍按请求数均分，长 prompt 请求会因画质分层被路由到高步数档，落在少数副本上形成热点；这些副本的 DiT 前向队列被拉长，尾延迟尖刺集中在长 prompt 场景，与画质投诉的分布重合。诊断手段是按 prompt 长度与步数档位做二维打点，观察副本间的 P99 偏离度；偏离度超过阈值即触发步数档位的动态再平衡，把高步数请求打散到更多副本。回滚策略应分层：画质类故障回滚步数配方与引导嵌入版本，分布错配类故障回滚学生权重并锁定教师版本，路由类故障回滚调度权重而非模型本身。三类回滚的共同前提是学生权重、步数配方、引导嵌入三者版本号绑定发布，任一变更都可独立回退，避免一次回滚把已验证的画质档位一并拖回。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>回滚对象</th></tr></thead><tbody><tr><td>长 prompt 画质退化</td><td>按 prompt 长度分桶的 CLIP 分数下移</td><td>步数配方</td></tr><tr><td>换底模分布错配</td><td>整批分数同步下移、无零散尖刺</td><td>学生权重 + 教师版本锁</td></tr><tr><td>极端 CFG 尺度塌陷</td><td>尺度分桶过饱和率抬升</td><td>引导嵌入版本</td></tr><tr><td>批抖动 / OOM</td><td>显存高水位与批完成间隔方差</td><td>调度批上限</td></tr><tr><td>尾延迟尖刺 / 路由不均</td><td>副本间 P99 偏离度</td><td>调度权重</td></tr></tbody></table>\n<h3 id=\"alg-lcm-fewstep-sec-48\">四十八 · 对照轴：改采样轨迹，还是改数值与 kernel</h3>\n<p>把潜空间一致性少步采样放进 Blackwell 推理栈里，第一件要判断的事不是它有多快，而是它改的是哪一层。它的作用点在采样轨迹与 CFG 结构：把 20–50 步的 PF-ODE 积分压缩成 4–8 个离散时间点上的直接映射 $f_\\theta(x_t,t)\\approx x_0$，并把引导尺度并入条件嵌入，使单次前向替代双 batch。与之相邻的一批条目——DiT NVFP4 混合精度、FP8 注意力与 GEMM、MX 分块、分块 PTQ 校准、异步 FA3 注意力、特征缓存与块级跳步、混合分辨率补丁调度、VAE 分块并行解码——改的是数值格式、kernel 调度、缓存复用或空间分块。两类手段正交，因此可以叠加：少步把 $N_{\\text{step}}$ 从 30 压到 4–8，量化把每次前向的权重带宽与 Tensor Core 吞吐改善，二者相乘而非相加。</p>\n<p>正交不等于可随意组合。少步学生的输入分布是教师 PF-ODE 轨迹上的稀疏采样点，其激活动态范围与 20–50 步轨迹的密集采样并不相同；把为稠密轨迹校准的 PTQ scale 直接套到 4 步学生上，量化误差会被一致性映射放大成结构性偏差。工程判断是：量化校准必须在少步学生自己的轨迹上重做，或至少用少步轨迹的 $(x_t,x_0)$ 配对做校准集，而不是沿用教师侧的校准产物。反过来，若量化已经把单步时延压到很低，少步的边际收益会被摊薄——端到端里 $t_{\\text{VAE}}$ 与调度开销占比上升，此时应先动 VAE 分块解码而不是继续压步数。</p>\n<div class=\"formula\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}},\\qquad T_{\\text{e2e}}^{\\text{quant}}\\approx N_{\\text{step}}\\cdot \\alpha\\, t_{\\text{DiT}}+t_{\\text{VAE}}$$</div>\n<p>式中 $\\alpha$ 为量化后单步 DiT 前向的相对时延系数。少步把 $N_{\\text{step}}$ 降到 4–8，量化把 $\\alpha$ 压低，两者分别作用在乘积的两端；但当 $N_{\\text{step}}\\cdot\\alpha t_{\\text{DiT}}$ 已接近 $t_{\\text{VAE}}$ 时，继续优化前者的收益递减。这就是选型时先看端到端分解、再看单点优化的原因。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-49\">四十九 · 决策表：五类相邻手段的适用条件</h3>\n<p>下表把本卷相邻条目按“改动层、收益形态、前置条件、与本算法的冲突点”四列对齐，用于在给定业务约束下做取舍。表中不给出未经验证的数值，只标注定性方向。</p>\n<table class=\"mini\"><thead><tr><th>相邻手段</th><th>改动层</th><th>收益形态</th><th>前置条件</th><th>与少步采样的冲突点</th></tr></thead><tbody>\n<tr><td>NVFP4 / FP8 / MX 分块量化</td><td>数值格式与 GEMM kernel</td><td>降单步时延与权重带宽</td><td>需在目标轨迹上重新校准</td><td>校准集须覆盖 4–8 步稀疏轨迹，否则误差被一致性映射放大</td></tr>\n<tr><td>异步 FA3 注意力</td><td>注意力 kernel 调度</td><td>降注意力段时延、提 SM 占用</td><td>序列长度与 head 配置匹配</td><td>无直接冲突，但少步后注意力占比上升，收益权重变大</td></tr>\n<tr><td>特征缓存 / 块级跳步</td><td>跨步复用中间特征</td><td>减少实际前向次数</td><td>相邻步特征相似度足够高</td><td>与少步目标重叠：两者都在减前向次数，叠加易致画质叠加退化</td></tr>\n<tr><td>混合分辨率补丁调度</td><td>空间分块与分辨率</td><td>把算力集中到高信息区</td><td>需内容感知的分块策略</td><td>少步下每步信息量更大，粗分辨率块的低频误差更难被后续步修正</td></tr>\n<tr><td>VAE 分块并行解码</td><td>末端解码</td><td>降 $t_{\\text{VAE}}$、降解码显存峰值</td><td>分块重叠与接缝处理</td><td>无冲突；少步后 $t_{\\text{VAE}}$ 占比上升，此项优先级反而提高</td></tr>\n</tbody></table>\n<p>读表的方式是看“冲突点”列而非“收益形态”列。收益形态只说明单项能省什么，冲突点才决定两项能否同时开。特征缓存与少步采样是唯一一对目标重叠的手段：前者靠相邻步特征相似来跳步，后者靠一致性映射直接跨越大时间间隔，二者叠加会让有效前向次数降到 4 步以下，而少步学生并未在该步数上蒸馏，画质退化不可控。工程上应二选一，或把缓存只用于高噪段之外的局部块。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-50\">五十 · 与整流流直线采样器的分工</h3>\n<p>整流流直线采样器与少步一致性采样同属“减少积分误差”的家族，但机制不同：前者把概率流轨迹拉直，使 Euler 类求解器在大步长下仍能保持低离散化误差，步数下降来自轨迹曲率变小；后者用蒸馏学生直接学习任意时刻到 $x_0$ 的映射，步数下降来自映射本身被训练成少步可用。前者不需要教师-学生蒸馏，换底模只需重训整流流目标，冷启动成本低；后者绑定教师架构，换底模必须重训学生，冷启动成本高，但能把 CFG 双 batch 合并掉。</p>\n<p>选型判据是业务是否要求 CFG 结构简化。若服务端瓶颈在显存而非时延——双 batch 使激活显存翻倍、批大小上不去——一致性蒸馏的 CFG 合并带来显存与算力同时减半，是别的手段给不了的。若瓶颈只在时延且底模频繁更换，整流流直线采样器加中等步数更稳，因为它不引入教师绑定。伪代码层面的判断可以写成：</p>\n<div class=\"formula\">$$\\text{choose}=\\begin{cases}\\text{consistency}, &amp; \\text{显存受限}\\ \\wedge\\ \\text{底模稳定}\\ \\wedge\\ \\text{文本复杂度可控}\\\\ \\text{rectified-flow}, &amp; \\text{底模频繁更换}\\ \\vee\\ \\text{需保留完整 CFG 调节空间}\\end{cases}$$</div>\n<p>代价侧要看清：一致性蒸馏把引导尺度并入条件嵌入后，引导强度的可调区间收窄，极端尺度下易出现过饱和或结构塌陷；整流流保留外置 CFG，调节空间完整但每步仍是双 batch 或需批合并技巧。若产品需要按用户输入动态调引导强度，少步一致性路线的可调空间就是硬约束，此时应把 CFG 合并视为“用调节自由度换显存”的交易。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-51\">五十一 · 与阶段级扩散服务流水、分离式部署的关系</h3>\n<p>阶段级扩散服务流水把预填、去噪、解码拆成不同资源池，靠阶段间重叠提吞吐；少步采样改变的是去噪阶段的步数与每步结构，因而直接改变流水里各阶段的时长配比。原本去噪阶段占主导，流水按去噪节拍配置 GPU 数量；步数降到 4–8 后去噪时长缩短 4–8 倍，VAE 解码与请求编排的相对权重上升，若不同步调整资源配比，流水会出现解码段排队而去噪段空闲的倒挂。</p>\n<p>具体机制上，流水按阶段划分队列，每阶段的并发度由该阶段服务时间与 SLO 决定。设去噪阶段服务时间为 $N_{\\text{step}}\\cdot t_{\\text{DiT}}$，解码阶段为 $t_{\\text{VAE}}$，则两阶段所需实例数比例近似正比于各自服务时间乘以到达率。少步把前者压缩后，比例向解码倾斜。工程动作有两步：一是按新比例重分资源池，二是把 VAE 分块并行解码的优先级提前——这正是决策表里“少步后 $t_{\\text{VAE}}$ 占比上升”的落地含义。</p>\n<p>与分离式预填/解码的类比要谨慎：扩散没有自回归的 KV cache 增长，分离式部署的收益来自阶段异构资源匹配而非缓存复用。少步采样与分离式部署可叠加，但叠加后的调优点从“步数”转移到“阶段配比”。若沿用旧配比，端到端时延的下降幅度会明显小于 4–8 倍这个单点数字，因为瓶颈已不在去噪段。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-52\">五十二 · 分层步数与业务分档的决策规则</h3>\n<p>少步采样对文本复杂组合与细粒度文字生成退化明显，退化随文本复杂度上升。因此选型不是“全局设 4 步”，而是按业务分层设步数。可操作的规则是：以 prompt 的结构复杂度（实体数量、空间关系、需渲染的文字串长度）作为分档特征，低复杂度档走 4 步，中档走 6 步，高档回退到 8 步或直接走非蒸馏的稠密轨迹。分档阈值需用业务侧画质投诉数据回归，而非凭经验拍定。</p>\n<p>代价要算清：分档意味着同一服务内并存多个步数配置，批调度需按步数分组以保持连续批处理的批内一致性，否则同一 batch 内混入不同步数的请求会导致 scheduler 更新次数不齐、GPU 空转。分组会降低批的填充率，在低到达率时段尤为明显，这是分档的隐性吞吐代价。另一条代价是冷启动：蒸馏学生绑定教师架构，换底模必须重训，若业务同时维护多个底模，每个底模都要一套学生与一套分档阈值，重训与校准的工程量随底模数量线性增长。</p>\n<p>失败模式在此处最集中：若不分层选择步数，画质投诉会集中出现在长 prompt 场景；若直接复用旧学生配新底模，会出现分布错配与画质崩坏。诊断上应把“步数—文本复杂度—画质”三者做成监控维度，而不是只看端到端时延。当长 prompt 占比上升而平均时延不变时，说明分档规则未生效或高档请求被错误路由到低步数档。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-53\">五十三 · 叠加顺序与工程判断</h3>\n<p>多项手段同时上时的顺序不是随意的。先定采样轨迹层（少步或整流流），再定数值层（量化格式与校准集），最后定调度层（注意力 kernel、缓存、分块、VAE 并行）。理由是：轨迹层决定激活分布，数值层的校准必须建立在最终轨迹上；调度层的收益权重取决于前两层压缩后的时间分解。若顺序颠倒——先按稠密轨迹校准量化、再换少步学生——校准产物失效，需返工。</p>\n<p>一个具体判断落在端到端分解上：当 $N_{\\text{step}}\\cdot t_{\\text{DiT}}$ 仍显著大于 $t_{\\text{VAE}}$ 时，继续压步数或上量化都有明确收益；当二者接近时，收益转移到 VAE 分块并行解码与请求编排；当 $t_{\\text{VAE}}$ 反超时，少步已不是瓶颈，此时再降步数只会放大画质退化而不改善时延。这条判断线把“4–8 步、4–8 倍”这个单点数字还原成有条件的结论：倍数成立的前提是去噪段仍占主导，且业务文本复杂度落在低中档。越过这两个前提，少步采样的正确用法是作为分档体系里的一档，而不是全局默认。</p>\n\n<h3 id=\"alg-lcm-fewstep-sec-54\">五十四 · 同族取舍：步数压缩的边界与代价核算</h3>\n<p>本方案与同族加速手段的分工不在同一层：它改的是采样步数与 CFG 结构，而非数值格式或注意力 kernel，因此与 NVFP4 量化、FA3 注意力是叠加关系而非替代关系——量化省的是每步的字节搬运与 Tensor Core 吞吐，本方案省的是步数本身。决策时应先问\"瓶颈在步数还是在单步成本\"：若端到端时延主要由 $T_{\\text{e2e}}\\approx N_{\\text{step}}\\cdot t_{\\text{DiT}}+t_{\\text{VAE}}$ 中的 $N_{\\text{step}}$ 项主导，压缩到 4–8 步收益最直接；若 $t_{\\text{VAE}}$ 或单步访存已占大头，则应优先做量化与 kernel 替换，此时再压步数边际收益递减。与逐步蒸馏、少步 scheduler 调参等相邻路线相比，一致性蒸馏的独特约束是学生绑定教师架构，这决定了它是\"一次性投入换长期低时延\"的重资产选项，而非可随手切换的轻量开关。</p>\n<p>失效条件集中在两处。其一是语义复杂度：少步采样对文本复杂组合与细粒度文字生成退化明显，退化随 prompt 长度与组合深度上升，若不分层选择步数，画质投诉会集中出现在长 prompt 场景——工程上应按业务分层配置步数档位，对文字密集与多主体组合请求回退到更多步数或走标准扩散路径。其二是引导强度空间：CFG 蒸馏把引导尺度并入条件嵌入后，单次前向替代双 batch，显存与算力同时减半，但引导强度的可调区间收窄，极端尺度下易出现过饱和或结构塌陷，因此对外暴露的 guidance 参数必须收窄到蒸馏覆盖的范围，不能沿用教师模型的调参习惯。</p>\n<p>换底模是最容易被低估的系统代价。教师架构一旦更换，旧学生直接复用会造成分布错配与画质崩坏，必须重训，冷启动成本落在数据配对（教师跑 PF-ODE 生成 $(x_t,x_0)$）与蒸馏算力上，这段时间内该业务线无法享受 4–8 倍时延收益。下表给出按业务形态的取舍判断。</p>\n<table class=\"mini\"><thead><tr><th>业务形态</th><th>步数档位</th><th>主要风险</th><th>建议</th></tr></thead><tbody><tr><td>通用创意出图、短 prompt</td><td>4 步</td><td>低</td><td>首选本方案，叠加量化</td></tr><tr><td>含文字排版、多主体组合</td><td>6–8 步或回退</td><td>文字与组合退化</td><td>分层路由，保留标准扩散兜底</td></tr><tr><td>底模频繁迭代</td><td>—</td><td>重训冷启动</td><td>先评估重训频率再决定是否采用</td></tr><tr><td>单步成本已受显存带宽限制</td><td>—</td><td>边际收益低</td><td>优先 NVFP4 与注意力 kernel</td></tr></tbody></table>\n<p>容量规划上，4–8 步把单图 DiT 前向次数压到个位数，配合 CFG 蒸馏去掉双 batch，单卡可承载的并发请求数随之上升，SLO 达标所需的 GPU 数量按步数比例下降；但这一收益以画质分层为代价，容量模型必须按业务分层的步数分布加权，而非统一按 4 步估算，否则长 prompt 请求回退会吃掉预留余量。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2023 · 特征缓存与注意力稀疏</td></tr><tr><td>解决什么</td><td>标准扩散需 20–50 步 UNet/DiT 前向，单张图端到端时延被步数线性放大，服务端 GPU 利用率与单位成本难…</td></tr><tr><td>一句话机制</td><td>在 latent 空间蒸馏一致性模型，把任意时刻的 PF-ODE 轨迹点直接映射回 x0，用 4–8 步完成采样，并保…</td></tr><tr><td>代价与失效</td><td>少步采样对文本复杂组合与细粒度文字生成退化明显，需按业务分层选择步数；蒸馏学生绑定教师架构，换底模需重训，冷启动成本高</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-lcm-fewstep · 共 8 个片段</p>\n";break;}}})();
